comms.text:
@1 אִם בִּקְיָמַי תְּהָכוּן וְיָת פִּקּוֹדַי תִּטְּרוּן וְתַעְבְּדוּן יָתְהוֹן:
@2 וְאֶתֵּן מַטְרֵיכוֹן בְּעִדָּנְהוֹן וְתִתֵּן אַרְעָא עֲלַלְתָּא וְאִילַן חַקְלָא יִתֵּן אִבֵּיהּ:
@3 וִיעָרַע לְכוֹן דְּיָשָׁא יָת קְטָפָא וּקְטָפָא יְעָרַע לְאַפּוֹקֵי בַר זַרְעָא וְתֵיכְלוּן לַחְמְכוֹן לְמִשְׂבַּע וְתֵיתְבוּן לְרָחְצָן בְּאַרְעֲכוֹן:
@4 וְאֶתֵּן שְׁלָמָא בְּאַרְעָא וְתִשְׁרוּן וְלֵית דְּמָנִיד וֶאֱבַטֵּל חַיְתָא בִשְׁתָּא מִן אַרְעָא וּדְקָטְלִין בְּחַרְבָּא לָא יְעִדּוּן בְּאַרְעֲכוֹן:
@5 וְתִרְדְּפוּן יָת בַּעֲלֵי דְבָבֵיכוֹן וְיִפְּלוּן קֳדָמֵיכוֹן לְחַרְבָּא:
@6 וְיִרְדְּפוּן מִנְּכוֹן חַמְשָׁא מְאָה וּמְאָה מִנְּכוֹן לְרִבּוֹתָא יֵעִירְקוּן וְיִפְּלוּן בַּעֲלֵי דְבָבֵיכוֹן קֳדָמֵיכוֹן לְחַרְבָּא:
@7 וְאֶתְפְּנִי בְמֵימְרִי לְאוֹטָבָא לְכוֹן וְאַפֵּשׁ יָתְכוֹן וְאַסְגֵּי יָתְכוֹן וַאֲקֵם יָת קְיָמִי עִמְּכוֹן:
@8 וְתֵיכְלוּן עַתִּיקָא דְּעַתִּיק וְעַתִּיקָא מִן קֳדָם חֲדַתָּא תְּפַנּוּן:
@9 וְאֶתֵּן מַשְׁכְּנִּי בֵּינֵיכוֹן וְלָא יְרַחֵק מֵימְרִי יָתְכוֹן:
@10 וְאַשְׁרֵי שְׁכִינְתִּי בֵּינֵיכוֹן וְאֶהֱוֵי לְכוֹן לֶאֱלָהּ וְאַתּוּן תְּהוֹן קֳדָמַי לְעָם:
@11 אֲנָא יְיָ אֱלָהָכוֹן דִּי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם מִלְּמֶהֱוֵי לְהוֹן עַבְדִּין וְתַבָּרִית נִיר עַמְמַיָּא מִנְּכוֹן וְדַבָּרִית יָתְכוֹן לְחֵרוּתָא:
@12 וְאִם לָא תְקַבְּלוּן לְמֵימְרִי וְלָא תַעְבְּדוּן יָת כָּל פִּקּוּדַיָּא הָאִלֵּין:
@13 וְאִם בִּקְיָמַי תְּקוֹצוּן וְאִם יָת דִּינַי תְּרַחֵק נַפְשְׁכוֹן בְּדִיל דְּלָא לְמֶעְבַּד יָת כָּל פִּקּוֹדַי לְאַשְׁנָיוּתְכוֹן יָת קְיָמִי:
@14 אַף אֲנָא אֶעְבַּד דָּא לְכוֹן וְאַסְעַר עֲלֵיכוֹן בַּהֶלְתָּא יָת שַׁחֶפְתָּא וְיָת קַדַּחְתָּא מְחַשְּׁכָן עַיְנִין וּמַפְּחַן נְפָשׁ וְתִזְרְעוּן לְרֵיקָנוּן זַרְעֲכוֹן וְיֵיכְלֻנֵּיהּ בַּעֲלֵי דְבָבֵיכוֹן:
@15 וְאֶתֵּן רוּגְזִי בְּכוֹן וְתִתַּבְּרוּן קֳדָם בַּעֲלֵי דְבָבֵיכוֹן וְיִרְדּוּן בְּכוֹן סַנְאֵכוֹן וְתֵעִירְקוּן וְלֵית דְּרָדִיף יָתְכוֹן:
@16 וְאִם עַד אִלֵּין לָא תְקַבְּלוּן לְמֵימְרִי וְאוֹסֵף לְמִרְדֵּי יָתכוֹן שְׁבַע עַל חוֹבֵיכוֹן:
@17 וְאֶתְבַּר יָת יְקַר תָּקְפְּכוֹן וְאֶתֵּן יָת שְׁמַיָּא דִי עִלָּוֵיכוֹן תַּקִּיפִין כְּפַרְזְלָא מִלַּאֲחָתָא מִטְרָא וְאַרְעָא דִתְחוֹתֵיכוֹן חֲסִינָא כִנְחָשָׁא מִלְּמֶעְבַּד פֵּירִין:
@18 וִיסוּפוּן לְרֵיקָנוּ חֵילֵיכוֹן וְלָא תִתֵּן אַרְעֲכוֹן יָת עֲלַלְתַּהּ וְאִילַן אַרְעָא לָא יִתֵּן אִבֵּיהּ:
@19 וְאִם תְּהָכוּן קֳדָמַי בְּקַשְׁיוּ וְלָא תֵיבוּן לְקַבָּלָא לְמֵימְרִי וְאוֹסֵף לֶאֱתָאָה עֲלֵיכוֹן מָחָא שְׁבַע כְּחוֹבֵיכוֹן:
@20 וֶאֱגָרֵי בְכוֹן יָת חֵוַת בָּרָא וּתְתַכֵּל יָתְכוֹן וּתְשֵׁיצֵי יָת בְּעִירְכוֹן וְתַזְעֵר יָתְכוֹן וִיצַדְיָן אוֹרְחָתְכוֹן:
@21 וְאִם בְּאִלֵּין לָא תִתְרְדוּן לְמֵימְרִי וּתְהָכוּן קֳדָמַי בְּקַשְׁיוּ:
@22 וְאֵהַךְ אַף אֲנָא עִמְּכוֹן בְּקַשְׁיוּ וְאַלְקֵי יָתְכוֹן אַף אֲנָא שְׁבַע עַל חוֹבֵיכוֹן:
@23 וְאַיְתִי עֲלֵיכוֹן דְּקָטְלִין בְּחַרְבָּא וְיִתְפָּרְעוּן מִנְּכוֹן פֻּרְעֲנוּתָא עַל דַּעֲבַרְתּוּן עַל פִּתְגָּמֵי אוֹרַיְתָא וְתִתְכַּנְּשׁוּן לְקִרְוֵיכוֹן וֶאֱגָרֵי מוֹתָנָא בֵּינֵיכוֹן וְתִתְמַסְּרוּן בִּידָא דְסָנְאָה:
@24 בִּדְאִתְּבַר לְכוֹן סָעִיד מֵיכְלָא וְיָפְיָן עֲסַר נְשִׁין לַחְמְכוֹן בְּתַנּוּרָא חַד וִיתִיבוּן לַחְמְכוֹן בְּמַתְקְלָא וְתוֹכְלוּן וְלָא תִשְׂבְּעוּן:
@25 וְאִם בְּדָא לָא תְקַבְּלוּן לְמֵימְרִי וּתְהָכוּן קֳדָמַי בְּקַשְׁיוּ:
@26 וְאֵהַךְ עִמְּכוֹן בִּתְקוֹף רְגָז וְאִרְדֵּי יָתְכוֹן אַף אֲנָא שְׁבַע עַל חוֹבֵיכוֹן:
@27 וְתֵיכְלוּן בְּשַׂר בְּנֵיכוֹן וּבְשַׁר בְּנָתֵיכוֹן תֵּיכְלוּן:
@28 וֶאֱשֵׁיצֵי יָת בָּמָתֵיכוֹן וֶאֱקַצֵּץ יָת חֲנִיסְנְסֵיכוֹן וְאֶתֵּן יָת פִּגְרֵיכוֹן עַל פִּגּוּר טַעֲוָתְכוֹן וִירַחֵק מֵימְרִי יָתְכוֹן:
@29 וְאֶתֵּן יָת קִרְוֵיכוֹן צָדָא וְאֶצְדֵּי יָת מַקְדְּשֵׁיכוֹן וְלָא אֲקַבֵּל בְּרַעֲוָא קֻרְבַּן כְּנִשָּׁתְכוֹן:
@30 וְאֶצְדֵּי אֲנָא יָת אַרְעָא וִיצָרְיוּן עֲלַהּ בַּעֲלֵי דְבָבֵיכוֹן דְּיָתְבוּן בַּהּ:
@31 וְיָתְכוֹן אֲבַדַּר בֵּינֵי עַמְמַיָּא וֶאֱגָרֵי בַתְרֵיכוֹן דְּקָטְלִין בְּחַרְבָּא וּתְהֵי אַרְעֲכוֹן צָדְיָא וְקִרְוֵיכוֹן יְהוֹן חָרְבָּא:
@32 בְּכֵן תַּרְעֵי אַרְעָא יָת שְׁמִטָּהָא כֹּל יוֹמִין דִּי צְדִיאַת וְאַתּוּן בְּאַרַע בַּעֲלֵי דְבָבֵיכוֹן בְּכֵן תַּשְׁמֵט אַרְעָא וְתַרְעֵי יָת שְׁמִטָּהָא:
@33 כָּל יוֹמִין דִּי צְדִיאַת תַּשְׁמֵט יָת דִּי לָא שְׁמֵטַת בִּשְׁמִטֵּיכוֹן כַּד הֲוֵיתוּן יָתְבִין עֲלַהּ:
@34 וּדְיִשְׁתַּאֲרוּן בְּכוֹן וְאָעֵל תַּבְרָא בְּלִבְּהוֹן בְּאַרְעֲתָא דְּסַנְאֵיהוֹן וְיִרְדּוֹף יָתְהוֹן קַל טַרְפָּא דְשַׁקִּיף וְיֵעַרְקוּן כְּמֵעִירוֹק מִן קֳדָם דְּקָטְלִין בְּחַרְבָּא וְיִפְּלוּן וְלֵית דְּרָדִיף:
@35 וְיִתַּקְלוּן גְּבַר בְּאָחוּהִי כְּמִקָּדָם דְקָטְלִין בְּחַרְבָּא וְרָדִיף לָיִת וְלָא תְהֵי לְכוֹן תְּקוּמָה קֳדָם בַּעֲלֵי דְבָבֵיכוֹן:
@36 וְתֵבְדוּן בֵּינֵי עַמְמַיָּא וּתְגַמַּר יָתְכוֹן אֲרַע בַּעֲלֵי דְבָבֵיכוֹן:
@37 וּדְיִשְׁתָּאֲרוּן בְּכוֹן יִתִּמְסוּן בְּחוֹבֵיהוֹן בְּאַרְעֲתָא בַּעֲלֵי דְבָבֵיכוֹן וְאַף בְּחוֹבֵי אֲבָהַתְהוֹן בִּישַׁיָּא דַּאֲחִידִין בִּידֵיהוֹן יִתִּמְסוּן:
@38 וִיוַדּוּן יָת חוֹבֵיהוֹן וְיָת חוֹבֵי אֲבָהַתְהוֹן בְּשִׁקְרְהוֹן דְּשַׁקָּרוּ קֳדָמָי וְאַף דִּי הַלִּיכוּ קֳדָמַי בְּקַשְׁיוּ:
@39 אַף אֲנָא אֱהַךְ עִמְּהוֹן בְּקַשְׁיוּ וְאָעֵיל יָתְהוֹן בְּאַרַע בַּעֲלֵי דְבָבֵיהוֹן אוֹ בְכֵן יִתָּבַר לִבְּהוֹן טַפְשָׁא וּבְכֵן יִרְעוּן יָת חוֹבֵיהוֹן:
@40 וְדָכִירְנָא יָת קְיָמִי דְעִם יַעֲקוֹב וְאַף יָת קְיָמִי דְעִם יִצְחָק וְאַף יָת קְיָמִי דְעִם אַבְרָהָם אֲנָא דָכִיר וְאַרְעָא אֲנָא דָכִיר:
@41 וְאַרְעָא תִתְרְטֵשׁ מִנְּהוֹן וְתַרְעֵי יָת שְׁמִטָּהָא בְּדִצְדִיאַת מִנְּהוֹן וְאִנּוּן יִרְעוּן יָת חוֹבֵיהוֹן לְוָטִין חֳלַף בִּרְכָן אַיְתִי עֲלֵיהוֹן בְּדִיל דִּבְדִינַי קָצוּ וְיָת קְיָמַי רְחֵקַת נַפְשְׁהוֹן:
@42 וְאַף בְּרַם דָּא בְּמֵהֱוֵיהוֹן בְּאַרַע בַּעֲלֵי דְבָבֵיהוֹן לָא אַרְטֵשִׁנּוּן וְלָא אַרְחֵקִנּוּן לְשֵׁיצָיוּתְהוֹן לְאַשְׁנָאָה קְיָמִי עִמְּהוֹן אֲרֵי אֲנָא יְיָ אֱלָהֲהוֹן:
@43 וְדָכִירְנָא לְהוֹן קְיַם קַדְמָאֵי דִּי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם לְעֵינֵי עַמְמַיָּא לְמֵהֱוֵי לְהוֹן לֵאלָהָא אֲנָא יְיָ:
@44 אִלֵּין קְיָמַיָּא וְדִינַיָּא וְאוֹרָיָתָא דִּי יְהַב יְיָ בֵּין מֵימְרֵיהּ וּבֵין בְּנֵי יִשְׂרָאֵל בְּטוּרָא דְסִינַי בִּידָא דְמשֶׁה:
@45 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@46 מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְּבַר אֲרֵי יַפְרֵשׁ נְדַר בְּפֻרְסַן נַפְשָׁתָא קֳדָם יְיָ:
@47 וִיהֵי פֻרְסָנֵיהּ דְּכוּרָא מִבַּר עֶסְרִין שְׁנִין וְעַד בַּר שִׁתִּין שְׁנִין וִיהֵי פֻרְסָנֵיהּ חַמְשִׁין סִלְעִין דִּכְסַף בְּסִלְעֵי קוּדְשָׁא:
@48 וְאִם נְקוּבְתָא הִיא וִיהֵי פֻרְסָנֵיהּ תְּלָתִין סִלְעִין:
@49 וְאִם מִבַּר חֲמֵשׁ שְׁנִין וְעַד בַּר עֶסְרִין שְׁנִין וִיהֵי פֻרְסָנֵיהּ דְּכוּרָא עֶסְרִין סִלְעִין וְלִנְקוּבְתָּא עֲסַר סִלְעִין:
@50 וְאִם מִבַּר יַרְחָא וְעַד בַּר חֲמֵשׁ שְׁנִין וִיהֵי פֻרְסָנֵיהּ דְּכוּרָא חֲמֵשׁ סִלְעִין דִּכְסָף וְלִנְקוּבְתָא פֻרְסָנַהּ תְּלַת סִלְעִין דִּכְסָף:
@51 וְאִם מִבַּר שִׁתִּין שְׁנִין וּלְעֵלָּא אִם דְּכוּרָא וִיהֵי פֻרְסָנֵיהּ חֲמֵשׁ עֶסְרֵי סִלְעִין וְלִנְקוּבְתָא עֲסַר סִלְעִין:
@52 וְאִם מִסְכֵּן הוּא מִפֻּרְסָנֵּיהּ וִיקִימִנֵּיהּ קֳדָם כַּהֲנָא וְיִפְרוֹס יָתֵיהּ כַּהֲנָא עַל מֵימַר דִּי תַדְבֵּק יְדָא דְנוֹדֵרָא יִפְרְסִנֵּיהּ כַּהֲנָא:
@53 וְאִם בְּעִירָא דִּי יְקָרְבוּן מִנַּהּ קֻרְבָּנָא קֳדָם יְיָ כֹּל דִּי יִתֵּן מִנֵּיהּ קֳדָם יְיָ יְהֵי קוּדְשָׁא:
@54 לָא יְחַלְּפִנֵּיהּ וְלָא יְעִבַּר יָתֵיהּ טַב בְּבִישׁ אוֹ בִישׁ בְּטָב וְאִם חַלָּפָא יְחַלֵּף בְּעִירָא בִּבְעִירָא וִיהֵי הוּא וְחִלּוּפֵיהּ יְהֵי קַדִּישׁ:
@55 וְאִם כָּל בְּעִירָא מְסָאָבָא דִּי לָא יְקָרְבוּן מִנַּהּ קֻרְבָּנָא קֳדָם יְיָ וִיקִים יָת בְּעִירָא קֳדָם כַּהֲנָא:
@56 וְיִפְרוֹס כַּהֲנָא יָתַהּ בֵּין טַב וּבֵין בִּישׁ כְּפֻרְסָנָא דְכַהֲנָא כֵּן יְהֵי:
@57 וְאִם מִפְרַק יִפְרְקֻנַּהּ וְיוֹסֵף חֻמְשֵׁיהּ עַל פֻּרְסָנֵיהּ:
@58 וּגְבַר אֲרֵי יַקְדֵּשׁ יָת בֵּיתֵיהּ קוּדְשָׁא קֳדָם יְיָ וְיִפְרְסִנֵּיהּ כַּהֲנָא בֵּין טַב וּבֵין בִּישׁ כְּמָא דִּי יִפְרוֹס יָתֵיהּ כַּהֲנָא כֵּן יְקוּם:
@59 וְאִם דְּאַקְדֵּשׁ יִפְרוֹק יָת בֵּיתֵיהּ וְיוֹסֵף חֹמֶשׁ כְּסַף פֻּרְסָנֵיהּ עֲלוֹהִי וִיהֵי לֵיהּ:
@60 וְאִם מֵחֲקַל אַחֲסַנְתֵּיהּ יַקְדִּישׁ גְּבַר קָדָם יְיָ וִיהֵי פֻרְסָנֵיהּ לְפוּם זַרְעֵיהּ בַּר זְרַע כּוּר שְׂעוֹרִין בְּחַמְשִׁין סִלְעִין דִּכְסָף:
@61 אִם מִשַּׁתָּא דְיוֹבֵלָא יַקְדֵּשׁ חַקְלֵיהּ כְּפֻרְסָנֵיהּ יְקוּם:
@62 וְאִם בָּתַר יוֹבֵלָא יַקְדֵּשׁ חַקְלֵיהּ וִיחַשֵּׁב לֵיהּ כַּהֲנָא יָת כַּסְפָּא עַל מֵימַר שְׁנַיָּא דְּאִשְׁתָּאָרָן עַד שַׁתָּא דְיוֹבֵלָא וְיִתִּמְנַע מִפֻּרְסָנֵיהּ:
@63 וְאִם מִפְרַק יִפְרוֹק יָת חַקְלָא דְּאַקְדֵּשׁ יָתֵיהּ וְיוֹסֵף חֹמֶשׁ כְּסַף פֻּרְסָנֵיהּ עֲלוֹהִי וִיקוּם לֵיהּ:
@64 וְאִם לָא יִפְרוֹק יָת חַקְלָא וְאִם זַבִּין יָת חַקְלָא לִגְבַר אָחֳרָן לָא יִתְפָּרָק עוֹד
@65 וִיהֵי חַקְלָא בְּמִפְּקֵיהּ בְּיוֹבֵלָא קוּדְשָׁא קֳדָם יְיָ כַּחֲקַל חֶרְמָא לְכַהֲנָא תְּהֵי אַחֲסַנְתֵּיהּ:
@66 וְאִם יָת חֲקַל זְבִינוֹהִי דִּי לָא מֵחֲקַל אַחֲסַנְתֵּיהּ יַקְדֵּשׁ קֳדָם יְיָ:
@67 וִיחַשֶּׁב לֵיהּ כַּהֲנָא יָת מִנְיַן פֻּרְסָנֵּיהּ עַד שַׁתָּא דְיוֹבֵלָא וְיִתֵּן יָת פֻּרְסָנֵיהּ בְּיוֹמָא הַהוּא קוּדְשָׁא קֳדָם יְיָ:
@68 בְּשַׁתָּא דְיוֹבֵלָא יְתוּב חַקְלָא לְדִזְבָּנֵיהּ מִנֵּיהּ לְדְדִילֵיהּ אַחֲסָנַת אַרְעָא:
@69 וְכָל פֻּרְסָנֵיהּ יְהֵי בְּסִלְעֵי קוּדְשָׁא עֶסְרִין מָעִין יְהֵי סִלְעָא:
@70 בְּרַם בּוּכְרָא דִּי יִתְבַּכַּר קֳדָם יְיָ בִּבְעִירָא לָא יַקְדֵּשׁ גְּבַר יָתֵיהּ אִם תּוֹר אִם אִמַּר דַּיְיָ הוּא:
@71 וְאִם בִּבְעִירָא מְסָאָבָא וְיִפְרוֹק בְּפֻרְסָנֵיהּ וְיוֹסֵף חֻמְשֵׁיהּ עֲלוֹהִי וְאִם לָא יִתְפָּרַק וְיִזְדַּבַּן בְּפֻרְסָנֵיהּ:
@72 בְּרַם כָּל חֶרְמָא דִּי יַחֲרֵם גְּבַר קֳדָם יְיָ מִכָּל דִּי לֵיהּ מֵאֲנָשָׁא וּבְעִירָא וּמֵחֲקַל אַחֲסַנְתֵּיהּ לָא יִזְדַּבַּן וְלָא יִתְפָּרָק כָּל חֶרְמָא קֹדֶשׁ קוּדְשִׁין הוּא קֳדָם יְיָ:
@73 כָּל חֶרְמָא דִּי יִתַּחְרַם מִן אֱנָשָׁא לָא יִתְפָּרָק אִתְקְטָלָא יִתְקְטֵל:
@74 וְכָל מַעְשְׂרָא דְאַרְעָא מִזַּרְעָא דְאַרְעָא מִפֵּרֵי אִילָנָא דַּיְיָ הוּא קוּדְשָׁא קֳדָם יְיָ:
@75 וְאִם מִפְרַק יִפְרוֹק גְּבַר מִמַּעַשְׂרֵיהּ חֻמְשֵׁיהּ יוֹסֵף עֲלוֹהִי:
@76 וְכָל מַעֲשַׂר תּוֹרִין וְעָן כֹּל דְּיֵעִבַּר תְּחוֹת חֻטְרָא עֲשִׂירָאָה יְהֵי קַדִּישׁ קֳדָם יְיָ:
@77 לָא יְבַקַּר בֵּין טַב לְבִישׁ וְלָא יְחַלְּפִנֵּיהּ וְאִם חַלָּפָא יְחַלְּפִנֵּיהּ וִיהֵי הוּא וְחִלּוּפֵיהּ יְהֵי קוּדְשָׁא לָא יִתְפָּרָק:
@78 אִלֵּין פִּקּוֹדַיָּא דִּי פַקִּיד יְיָ יָת משֶׁה לְוָת בְּנֵי יִשְׂרָאֵל בְּטוּרָא דְּסִינָי:

@1 **אם בחקתי תלכו.** יָכוֹל זֶה קִיּוּם הַמִּצְווֹת, כְּשֶׁהוּא אוֹמֵר וְאֶת מִצְוֹתַי תִּשְׁמְרוּ וַעֲשִיתֶם אֹתָם הֲרֵי קִיּוּם הַמִּצְווֹת אָמוּר, הָא מָה אֲנִי מְקַיֵּם אִם בְּחֻקֹּתַי תֵּלֵכוּ? שֶׁתִּהְיוּ עֲמֵלִים בַּתּוֹרָה (ספרא):
@1 **ואת מצותי תשמרו.** הֱווּ עֲמֵלִים בַּתּוֹרָה עַל מְנָת לִשְׁמֹר וּלְקַיֵּם, כְּמוֹ שֶׁנֶּאֱמַר "וּלְמַדְתֶּם אֹתָם וּשְׁמַרְתֶּם לַעֲשֹׂתָם" (דברים ה'):
@2 **בעתם.** בְּשָׁעָה שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לָצֵאת, כְּגוֹן בְּלֵילֵי שַׁבָּתוֹת (ספרא; תענית כ"ג):
@2 **ועץ השדה.** הֵן אִילָנֵי סְרָק, וַעֲתִידִין לַעֲשׂוֹת פֵּרוֹת (ספרא):
@3 **והשיג לכם דיש את בציר.** שֶׁיְּהֵא הַדַּיִשׁ מְרֻבֶּה, וְאַתֶּם עֲסוּקִים בּוֹ עַד הַבָּצִיר, וּבַבָּצִיר תַּעַסְקוּ עַד שְׁעַת הַזֶּרַע (ספרא):
@3 **ואכלתם לחמכם לשבע.** אוֹכֵל קִמְעָא וְהוּא מִתְבָּרֵךְ בְּמֵעָיו:
@4 **ונתתי שלום.** שֶׁמָּא תֹאמְרוּ, הֲרֵי מַאֲכָל וַהֲרֵי מִשְׁתֶּה, אִם אֵין שָׁלוֹם אֵין כְּלוּם, תַּ"לֹ אַחַר כָּל זֹאת "וְנָתַתִּי שָׁלוֹם בָּאָרֶץ"; מִכָּאן שֶׁהַשָּׁלוֹם שָׁקוּל כְּנֶגֶד הַכֹּל, וְכֵן הוּא אוֹמֵר (ישעיה מ"ה) "עוֹשֶׂה שָׁלוֹם וּבוֹרֵא אֶת הַכֹּל":
@4 **וחרב לא תעבר בארצכם.** אֵצָ"לֹ שֶׁלֹּא יָבֹאוּ לַמִּלְחָמָה, אֶלָּא אֲפִלּוּ לַעֲבֹר דֶּרֶךְ אַרְצְכֶם מִמְּדִינָה לִמְדִינָה (ספרא):
@5 **לפניכם לחרב.** אִישׁ בְּחֶרֶב רֵעֵהוּ (שם):
@6 **ורדפו מכם.** מִן הַחַלָּשִׁים שֶׁבָּכֶם וְלֹא מִן הַגִּבּוֹרִים שֶׁבָּכֶם (שם):
@6 **חמשה מאה ומאה מכם רבבה.** וְכִי כָךְ הוּא הַחֶשְׁבּוֹן? וַהֲלֹא לֹא הָיָה צָרִיךְ לוֹמַר אֶלָּא מֵאָה מִכֶּם שְׁנֵי אֲלָפִים יִרְדֹּפוּ, אֶלָּא אֵינוֹ דּוֹמֶה מֻעֲטִין הָעוֹשִׂים אֶת הַתּוֹרָה לִמְרֻבִּין הָעוֹשִׂין אֶת הַתּוֹרָה (שם):
@6 **ונפלו איביכם וגו'.** שֶׁיִּהְיוּ נוֹפְלִין לִפְנֵיכֶם שֶׁלֹּא כְדֶרֶךְ הָאָרֶץ (שם):
@7 **ופניתי אליכם.** אֶפְנֶה מִכָּל עֲסָקַי לְשַׁלֵּם שְׂכַרְכֶם. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁשָּׂכַר פּוֹעֲלִים וְכוּ', כִּדְאִיתָא בְּתֹ"כֹּ:
@7 **והפריתי אתכם.** בִּפְרִיָּה וּרְבִיָּה:
@7 **והרביתי אתכם.** בְּקוֹמָה זְקוּפָה (ספרא):
@7 **והקימתי את בריתי אתכם.** בְּרִית חֲדָשָׁה, לֹא כַבְּרִית הָרִאשׁוֹנָה שֶׁהֵפַרְתֶּם אוֹתָהּ אֶלָּא בְּרִית חֲדָשָׁה שֶׁלֹּא תּוּפַר, שֶׁנֶּאֱמַר (ירמיהו ל"א) "וְכָרַתִּי אֶת בֵּית יִשְׂרָאֵל וְאֶת בֵּית יְהוּדָה בְּרִית חֲדָשָׁה לֹא כַבְּרִית וְגוֹ'" (ספרא):
@8 **ואכלתם ישן נושן.** הַפֵּרוֹת יִהְיוּ מִשְׁתַּמְרִין וְטוֹבִים לְהִתְיַשֵּׁן, שֶׁיְּהֵא יָשָׁן הַנּוֹשָׁן שֶׁל שָׁלוֹשׁ שָׁנִים יָפֶה לֶאֱכֹל מִשֶּׁל אֶשְׁתָּקַד (בבא בתרא צ"א):
@8 **וישן מפני חדש תוציאו.** שֶׁיִּהְיוּ הַגְּרָנוֹת מְלֵאוֹת חָדָשׁ וְהָאוֹצָרוֹת מְלֵאוֹת יָשָׁן, וּצְרִיכִים אַתֶּם לְפַנּוֹת הָאוֹצָרוֹת לְמָקוֹם אַחֵר, לָתֵת הֶחָדָשׁ לְתוֹכָן (שם):
@9 **ונתתי משכני.** זֶה בֵּית הַמִּקְדָּשׁ (ספרא: עירובין ב'):
@9 **ולא תגעל נפשי.** אֵין רוּחִי קָצָה בָכֶם; כָּל גְּעִילָה לְשׁוֹן פְּלִיטַת דָּבָר הַבָּלוּעַ בְּדָבָר, כְּמוֹ "כִּי שָׁם נִגְעַל מָגֵן גִּבּוֹרִים" (שמואל ב א') — לֹא קִבֵּל הַמְּשִׁיחָה, שֶׁמּוֹשְׁחִין מָגֵן שֶׁל עוֹר בְּחֵלֶב מְבֻשָּׁל כְּדֵי לְהַחֲלִיק מֵעָלָיו מַכַּת חֵץ אוֹ חֲנִית, שֶׁלֹּא יִקֹּב הָעוֹר:
@10 **והתהלכתי בתוככם.** אֲטַיֵּל עִמָּכֶם בְּגַן עֵדֶן כְּאֶחָד מִכֶּם, וְלֹא תִהְיוּ מִזְדַּעְזְעִים מִמֶּנִּי, יָכוֹל לֹא תִירְאוּ מִמֶּנִּי, תַּ"לֹ "וְהָיִיתִי לָכֶם לֵאלֹהִים" (ספרא):
@11 **אני ה' אלהיכם.** כְּדַאי אֲנִי שֶׁתַּאֲמִינוּ בִי שֶׁאֲנִי יָכוֹל לַעֲשׂוֹת כָּל אֵלֶּה, שֶׁהֲרֵי הוֹצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרַיִם וְעָשִׂיתִי לָכֶם נִסִּים גְּדוֹלִים:
@11 **מטת.** כְּמִין יָתֵד בִּשְׁנֵי רָאשֵׁי הָעֹל הַמְעַכְּבִים הַמּוֹסֵרָה שֶׁלֹּא תֵצֵא מֵרֹאשׁ הַשּׁוֹר וְיַתִּיר הַקֶּשֶׁר, כְּמוֹ "עֲשֵֹה לְךָ מוֹסֵרוֹת וּמֹטוֹת" (ירמיהו כ"ז), קבילייא בְּלַעַז:
@11 **קוממיות.** בְּקוֹמָה זְקוּפָה (ספרא):
@12 **ואם לא תשמעו לי.** לִהְיוֹת עֲמֵלִים בַּתּוֹרָה, לָדַעַת מִדְרַשׁ חֲכָמִים. יָכוֹל לְקִיּוּם הַמִּצְווֹת? כְּשֶׁהוּא אוֹמֵר וְלֹא תַעֲשׂוּ וְגוֹ' הֲרֵי קִיּוּם מִצְווֹת אָמוּר, הָא מָה אֲנִי מְקַיֵּם וְאִם לֹא תִשְׁמְעוּ לִי? לִהְיוֹת עֲמֵלִים בַּתּוֹרָה, וּמַה תַּ"לֹ לִי? אֵין לִי אֶלָּא זֶה הַמַּכִּיר אֶת רִבּוֹנוֹ וּמְכַוֵּן לִמְרֹד בּוֹ, וְכֵן בְּנִמְרוֹד "גִּבּוֹר צַיִד לִפְנֵי ה'" (בראשית י'), שֶׁמַּכִּירוֹ וּמִתְכַּוֵּן לִמְרֹד בּוֹ, וְכֵן בְּאַנְשֵׁי סְדוֹם "רָעִים וְחַטָּאִים לַה' מְאֹד" (שם י"ג), מַכִּירִים אֶת רִבּוֹנָם וּמִתְכַּוְּנִים לִמְרֹד בּוֹ (ספרא):
@12 **ולא תעשו.** מִשֶּׁלֹּא תִלְמְדוּ לֹא תַעֲשׂוּ, הֲרֵי שְׁתֵּי עֲבֵרוֹת:
@13 **ואם בחקתי תמאסו.** מוֹאֵס בַּאֲחֵרִים הָעוֹשִׂים:
@13 **משפטי תגעל נפשכם.** שׂוֹנֵא הַחֲכָמִים:
@13 **לבלתי עשות.** מוֹנֵעַ אֶת אֲחֵרִים מֵעֲשׂוֹת:
@13 **את כל מצותי.** כּוֹפֵר שֶׁלֹּא צִוִּיתִים, לְכָךְ נֶאֱמַר "אֶת כָּל מִצְוֹתַי" וְלֹא נֶאֱמַר "אֶת כָּל הַמִּצְוֹת":
@13 **להפרכם את בריתי.** כּוֹפֵר בָּעִקָּר; הֲרֵי שֶׁבַע עֲבֵרוֹת, הָרִאשׁוֹנָה גוֹרֶרֶת הַשְּׁנִיָּה, וְכֵן עַד הַשְּׁבִיעִית, וְאֵלּוּ הֵן: לֹא לָמַד, וְלֹא עָשָׂה, מוֹאֵס בַּאֲחֵרִים הָעוֹשִׂים, שׂוֹנֵא אֶת הַחֲכָמִים, מוֹנֵעַ אֶת הָאֲחֵרִים, כּוֹפֵר בַּמִּצְווֹת, כּוֹפֵר בָּעִקָּר:
@14 **והפקדתי עליכם.** וְצִוִּיתִי עֲלֵיכֶם:
@14 **השחפת.** חֹלִי שֶׁמְּשַׁחֵף אֶת הַבָּשָׂר, אנפו"ליש בלעז, דּוֹמֶה לְנָפוּחַ שֶׁהוּקַלָּה נְפִיחָתוֹ וּמַרְאִית פָּנָיו זְעוּפָה:
@14 **הקדחת.** חֹלִי שֶׁמַּקְדִּיחַ אֶת הַגּוּף וּמְחַמְּמוֹ וּמַבְעִירוֹ, כְּמוֹ "כִּי אֵשׁ קָדְחָה בְאַפִּי" (דברים ל"ב):
@14 **מכלות עינים ומדיבת נפש.** הָעֵינַיִם צוֹפוֹת וְכָלוֹת לִרְאוֹת שֶׁיֵּקַל וְיֵרָפֵא, וְסוֹף שֶׁלֹּא יֵרָפֵא, וְיִדְאֲבוּ הַנְּפָשׁוֹת שֶׁל מִשְׁפַּחְתּוֹ בְּמוֹתוֹ; כָּל תַּאֲוָה שֶׁאֵינָהּ בָּאָה וְתוֹחֶלֶת מְמֻשָּׁכָה קְרוּיָה כִלְיוֹן עֵינַיִם:
@14 **וזרעתם לריק.** תִּזְרְעוּ וְלֹא תִצְמַח, וְאִם תִּצְמַח **ואכלהו איביכם** :
@15 **ונתתי פני.** פְּנַאי שֶׁלִּי — פּוֹנֶה אֲנִי מִכָּל עֲסָקַי לְהָרַע לָכֶם:
@15 **ורדו בכם שנאיכם.** כְּמַשְׁמָעוֹ, יִשְׁלְטוּ בָכֶם: אַגָּדַת תֹּ"כֹּ מִפָּרָשָׁה זוֹ:
@15 **אף אני אעשה זאת.** אֵינִי מְדַבֵּר אֶלָּא בְּאַף, וְכֵן "אַף אֲנִי אֵלֵךְ עִמָּכֶם בְּקֶרִי" (פסוק מ"א):
@15 **והפקדתי עליכם.** שֶׁיִּהְיוּ הַמַּכּוֹת פּוֹקְדוֹת אֶתְכֶם מִזוֹ לְזוֹ, עַד שֶׁהָרִאשׁוֹנָה פְקוּדָה אֶצְלְכֶם, אָבִיא אַחֶרֶת וְאֶסְמְכֶנָּה לָהּ:
@15 **בהלה.** מַכָּה הַמְבַהֶלֶת אֶת הַבְּרִיּוֹת, וְאֵי זוֹ? זוֹ מַכַּת מוֹתָן:
@15 **את השחפת.** יֵשׁ לְךָ אָדָם שֶׁהוּא חוֹלֶה וּמֻטָּל בַּמִּטָּה אֲבָל בְּשָׂרוֹ שָׁמוּר עָלָיו, תַּ"לֹ "שַׁחֶפֶת", שֶׁהוּא נִשְׁחָף, אוֹ עִתִּים שֶׁהוּא נִשְׁחָף אֲבָל נֹחַ וְאֵינוֹ מַקְדִּיחַ, תַּ"לֹ "וְאֶת הַקַּדַּחַת", מְלַמֵּד שֶׁהוּא מַקְדִּיחַ, אוֹ עִתִּים שֶׁהוּא מַקְדִּיחַ אֲבָל סָבוּר הוּא בְעַצְמוֹ שֶׁיִּחְיֶה, תַּ"לֹ "מְכַלּוֹת עֵינַיִם", אוֹ הוּא אֵינוֹ סָבוּר בְּעַצְמוֹ שֶׁיִּחְיֶה, אֲבָל אֲחֵרִים סְבוּרִים שֶׁיִּחְיֶה, תַּ"לֹ "וּמְדִיבֹת נָפֶשׁ":
@15 **וזרעתם לריק זרעכם.** זוֹרְעָהּ וְאֵינָהּ מַצְמַחַת, וּמֵעַתָּה מָה אוֹיְבֵיכֶם בָּאִים וְאוֹכְלִים? תַּ"לֹ "וַאֲכָלֻהוּ אֹיְבֵיכֶם", הָא כֵיצַד? זוֹרְעָהּ שָׁנָה רִאשׁוֹנָה וְאֵינָהּ מַצְמַחַת, שָׁנָה שְׁנִיָּה מַצְמַחַת, וְאוֹיְבִים בָּאִים וּמוֹצְאִים תְּבוּאָה לִימֵי הַמָּצוֹר, וְשֶׁבִּפְנִים מֵתִים בָּרָעָב, שֶׁלֹּא לִקְּטוּ תְּבוּאָה אֶשְׁתָּקַד; דָּ"אַ: "וּזְרַעְתֶּם לָרִיק זַרְעֲכֶם", כְּנֶגֶד הַבָּנִים וְהַבָּנוֹת הַכָּתוּב מְדַבֵּר, שֶׁאַתָּה עָמֵל בָּהֶם וּמְגַדְּלָן, וְהַחֵטְא בָּא וּמְכַלֶּה אוֹתָם, שֶׁנֶּאֱמַר "אֲשֶׁר טִפַּחְתִּי וְרִבִּיתִי אֹיְבִי כִלָּם" (איכה ב'):
@15 **ונתתי פני בכם.** כְּמוֹ שֶׁנֶּאֱמַר בַּטּוֹבָה "וּפָנִיתִי אֲלֵיכֶם", כָּךְ נֶאֱמַר בָּרָעָה "וְנָתַתִּי פָנַי"; מָשְׁלוּ מָשָׁל, לְמֶלֶךְ שֶׁאָמַר לַעֲבָדָיו, פּוֹנֶה אֲנִי מִכָּל עֲסָקַי וְעוֹסֵק אֲנִי עִמָּכֶם לְרָעָה:
@15 **ונגפתם לפני איביכם.** שֶׁיְּהֵא הַמָּוֶת הוֹרֵג אֶתְכֶם מִבִּפְנִים, וּבַעֲלֵי דְבָבֵיכוֹן מַקִּיפִין אֶתְכֶם מִבַּחוּץ:
@15 **ורדו בכם שנאיכם.** שֶׁאֵינִי מַעֲמִיד שׂוֹנְאִים אֶלָּא מִכֶּם וּבָכֶם, שֶׁבְּשָׁעָה שֶׁאֻמּוֹת הָעוֹלָם עוֹמְדִים עַל יִשְׂרָאֵל, אֵינָם מְבַקְּשִׁים אֶלָּא מַה שֶּׁבַּגָּלוּי, שֶׁנֶאֱמַר "וְהָיָה אִם זָרַע יִשְׂרָאֵל וְעָלָה מִדְיָן וַעֲמָלֵק וּבְנֵי קֶדֶם וְגוֹ' וַיַּחֲנוּ עֲלֵיהֶם וַיַּשְׁחִיתוּ אֶת יְבוּל הָאָרֶץ" (שופטים ו'), אֲבָל בְּשָׁעָה שֶׁאֲעֲמִיד עֲלֵיכֶם מִכֶּם וּבָכֶם, הֵם מְחַפְּשִׂים אַחַר הַמַּטְמוֹנִיּוֹת שֶׁלָּכֶם, וְכֵן הוּא אוֹמֵר "וַאֲשֶׁר אָכְלוּ שְׁאֵר עַמִּי וְעוֹרָם מֵעֲלֵיהֶם הִפְשִׁיטוּ וְגוֹ'" (מיכה ג'):
@15 **ונסתם.** מִפְּנֵי אֵימָה:
@15 **ואין רדף אתכם.** מִבְּלִי כֹחַ (ספרא):
@16 **ואם עד אלה.** וְאִם בְּעוֹד אֵלֶּה **לא תשמעו** :
@16 **ויספתי.** עוֹד יִסּוּרִין אַחֵרִים:
@16 **שבע על חטאתיכם.** שֶׁבַע פֻּרְעָנֻיּוֹת עַל שֶׁבַע עֲבֵרוֹת הָאֲמוּרוֹת לְמַעְלָה:
@17 **ושברתי את גאון עזכם.** זֶה בֵּית הַמִּקְדָּשׁ, וְכֵן הוּא אוֹמֵר "הִנְנִי מְחַלֵּל אֶת מִקְדָּשִׁי גְּאוֹן עֻזְּכֶם" (יחזקאל כ"ד):
@17 **ונתתי את שמיכם כברזל ואת ארצכם כנחשה.** זוֹ קָשָׁה מִשֶּׁל מֹשֶׁה, שֶׁשָּׁם הוּא אוֹמֵר "וְהָיוּ שָׁמֶיךָ אֲשֶׁר עַל רֹאשְׁךָ נְחֹשֶׁת וְגו'" (דברים כ"ח), שֶׁיִּהְיוּ הַשָּׁמַיִם מַזִּיעִין כְּדֶרֶךְ שֶׁהַנְּחֹשֶׁת מַזִּיעָה, וְהָאָרֶץ אֵינָהּ מַזִּיעָה כְּדֶרֶךְ שֶׁאֵין הַבַּרְזֶל מַזִּיעַ, וְהִיא מְשַׁמֶּרֶת פֵּרוֹתֶיהָ, אֲבָל כָּאן הַשָּׁמַיִם לֹא יִהְיוּ מַזִּיעִין כְּדֶרֶךְ שֶׁאֵין הַבַּרְזֶל מַזִּיעַ, וִיהֵא חֹרֶב בָּעוֹלָם, וְהָאָרֶץ תְּהֵא מַזִּיעָה כְּדֶרֶךְ שֶׁהַנְּחֹשֶׁת מַזִּיעָה, וְהִיא מְאַבֶּדֶת פֵּרוֹתֶיהָ (ספרא):
@18 **ותם לריק כחכם.** הֲרֵי אָדָם שֶׁלֹּא עָמַל, שֶׁלֹּא חָרַשׁ, שֶׁלֹּא זָרַע, שֶׁלֹּא נִכֵּשׁ, שֶׁלֹּא כִּסֵּחַ, שֶׁלֹּא עָדַר, וּבִשְׁעַת הַקָּצִיר בָּא שִׁדָּפוֹן וּמַלְקֶה אוֹתוֹ, אֵין בְּכָךְ כְּלוּם, אֲבָל אָדָם שֶׁעָמַל וְחָרַשׁ וְזָרַע וְנִכֵּשׁ וְכִסֵּחַ וְעָדַר וּבָא שִׁדָּפוֹן וּמַלְקֶה אוֹתוֹ, הֲרֵי שִׁנָּיו שֶׁל זֶה קֵהוֹת:
@18 **ולא תתן ארצכם את יבולה.** אַף מַה שֶּׁאַתָּה מוֹבִיל לָהּ בִּשְׁעַת הַזֶּרַע (ספרא):
@18 **ועץ הארץ.** אֲפִלּוּ מִן הָאָרֶץ יְהֵא לָקוּי, שֶׁלֹּא יַחֲנִיט פֵּרוֹתָיו בִּשְׁעַת הַחֲנָטָה (שם):
@18 **לא יתן.** מְשַׁמֵּשׁ לְמַעְלָה וּלְמַטָּה, אָעֵץ וְאַפְּרִי:
@18 **לא יתן פריו.** כְּשֶׁהוּא מַפְרֶה מַשִּׁיר פֵּרוֹתָיו, הֲרֵי שְׁתֵּי קְלָלוֹת, וְיֵשׁ כָּאן שֶׁבַע פֻּרְעָנֻיּוֹת (ספרא):
@19 **ואם תלכו עמי קרי.** רַבּוֹתֵינוּ אָמְרוּ עֲרַאי, בְּמִקְרֶה, שֶׁאֵינוֹ אֶלָּא לִפְרָקִים, כֵּן תֵּלְכוּ עֲרַאי בְּמִצְווֹת; וּמְנַחֵם פֵּרֵשׁ לְשׁוֹן מְנִיעָה, וְכֵן "הֹקַר רַגְלְךָ" (משלי כ"ה), וְכֵן "יְקַר רוּחַ" (שם י"ז), וְקָרוֹב לָשׁוֹן זֶה לְתַרְגּוּמוֹ שֶׁל אֻנְקְלוֹס, לְשׁוֹן קֹשִׁי, שֶׁמַּקְשִׁין לִבָּם לִמָּנַע מֵהִתְקָרֵב אֵלַי:
@19 **שבע כחטאתיכם.** שֶׁבַע פֻּרְעָנֻיּוֹת אֲחֵרִים, בְּמִסְפַּר שֶׁבַע כְּחַטֹּאתֵיכֶם (ספרא):
@20 **והשלחתי.** לְשׁוֹן גֵּרוּי:
@20 **ושכלה אתכם.** אֵין לִי אֶלָּא חַיָּה מְשַׁכֶּלֶת שֶׁדַּרְכָּהּ בְּכָךְ, בְּהֵמָה שֶׁאֵין דַּרְכָּהּ בְּכָךְ מִנַּיִן? תַּ"לֹ "וְשֶׁן בְּהֵמֹת אֲשַׁלַּח בָּם" (דברים ל"ב), הֲרֵי שְׁתַּיִם. וּמִנַּיִן שֶׁתְּהֵא מְמִיתָה בִנְשִׁיכָתָהּ? תַּ"לֹ "עִם חֲמַת זֹחֲלֵי עָפָר" (שם), מָה אֵלּוּ נוֹשְׁכִין וּמְמִיתִין אַף אֵלּוּ נוֹשְׁכִין וּמְמִיתִין, כְּבָר הָיוּ שָׁנִים בְּאֶרֶץ יִשְׂרָאֵל חֲמוֹר נוֹשֵׁךְ וּמֵמִית, עָרוֹד נוֹשֵׁךְ וּמֵמִית:
@20 **ושכלה אתכם.** אֵלּוּ הַקְּטַנִּים:
@20 **והכריתה את בהמתכם.** מִבַּחוּץ:
@20 **והמעיטה אתכם.** מִבִּפְנִים:
@20 **ונשמו דרכיכם.** שְׁבִילִים גְּדוֹלִים וּשְׁבִילִים קְטַנִּים; הֲרֵי שֶׁבַע פֻּרְעָנֻיּוֹת: שֵׁן בְּהֵמָה, וְשֵׁן חַיָּה, חֲמַת זוֹחֲלֵי עָפָר, וְשִׁכְּלָה, וְהִכְרִיתָה, וְהִמְעִיטָה, וְנָשַׁמּוּ:
@21 **לא תוסרו לי.** לָשׁוּב אֵלַי:
@23 **נקם ברית.** יֵשׁ נָקָם שֶׁאֵינוֹ בַּבְּרִית, כְּדֶרֶךְ שְׁאָר נְקָמוֹת, וְזֶהוּ סִמּוּי עֵינָיו שֶׁל צִדְקִיָּהוּ (ספרא). דָּ"אַ: **נקם ברית** נִקְמַת בְּרִיתִי אֲשֶׁר עֲבַרְתֶּם. כָּל הֲבָאַת חֶרֶב שֶׁבַּמִּקְרָא הִיא מִלְחֶמֶת חֲיָלוֹת אוֹיְבִים:
@23 **ונאספתם.** מִן הַחוּץ אֶל תּוֹךְ הֶעָרִים מִפְּנֵי הַמָּצוֹר (שם):
@23 **ושלחתי דבר בתוככם.** עַ"יְ הַדֶּבֶר **ונתתם ביד** הָאוֹיְבִים הַצָּרִים עֲלֵיכֶם, לְפִי שֶׁאֵין מְלִינִים אֶת הַמֵּת בִּירוּשָׁלַיִם, וּכְשֶׁהֵם מוֹצִיאִים אֶת הַמֵּת לְקָבְרוֹ נִתָּנִין בְּיַד אוֹיֵב (שם):
@24 **מטה לחם.** לְשׁוֹן מִשְׁעָן, כְּמוֹ מַטֵּה עֹז (ירמיהו מ"ח):
@24 **בשברי לכם מטה לחם.** אֶשְׁבֹּר לָכֶם כָּל מִסְעַד אֹכֶל, וְהֵם חִצֵּי רָעָב (יחזקאל ה'):
@24 **ואפו עשר נשים לחמכם בתנור אחד.** מֵחֹסֶר עֵצִים (ספרא):
@24 **והשיבו לחמכם במשקל.** שֶׁתְּהֵא הַתְּבוּאָה נִרְקֶבֶת וְנַעֲשֵׂית פַּת נְפֹלֶת, וּמִשְׁתַּבֶּרֶת בַּתַּנּוּר, וְהֵן יוֹשְׁבוֹת וְשׁוֹקְלוֹת אֶת הַשְּׁבָרִים לְחַלְּקָם בֵּינֵיהֶם (שם):
@24 **ואכלתם ולא תשבעו.** זֶהוּ מְאֵרָה בְּתוֹךְ הַמֵּעַיִם בַּלֶּחֶם, הֲרֵי שֶׁבַע פֻּרְעָנֻיּוֹת: חֶרֶב, מָצוֹר, דֶּבֶר, שֶׁבֶר מַטֵּה לֶחֶם, חֹסֶר עֵצִים, פַּת נְפֹלֶת, מְאֵרָה בַמֵּעַיִם; וְנִתַּתֶּם אֵינָהּ מִן הַמִּנְיָן, הִיא הַחֶרֶב:
@28 **במתיכם.** מִגְדָּלִים וּבִירָנִיּוֹת:
@28 **חמניכם.** מִין עֲ"זָ שֶׁמַּעֲמִידִין עַל הַגַּגּוֹת, וְעַל שֵׁם שֶׁמַּעֲמִידִין בַּחַמָּה, קְרוּיִין חַמָּנִים (ספרא ויקרא י"ט):
@28 **ונתתי את פגריכם.** תְּפוּחֵי רָעָב הָיוּ, וּמוֹצִיאִים יִרְאָתָם מֵחֵיקָם וּמְנַשְּׁקִים אוֹתָם, וּכְרֵיסָן נִבְקַעַת וְנוֹפֵל עָלֶיהָ (ספרא; סנהדרין ס"ג):
@28 **וגעלה נפשי אתכם.** זֶה סִלּוּק שְׁכִינָה (ספרא):
@29 **ונתתי את עריכם חרבה.** יָכוֹל מֵאָדָם, כְּשֶׁהוּא אוֹמֵר וַהֲשִׁמֹּתִי אֲנִי אֶת הָאָרֶץ הֲרֵי אָדָם אָמוּר, הָא מָה אֲנִי מְקַיֵּם חָרְבָּה? מֵעוֹבֵר וָשָׁב:
@29 **והשמותי את מקדשיכם.** יָכוֹל מִן הַקָּרְבָּנוֹת, כְּשֶׁהוּא אוֹמֵר וְלֹא אָרִיחַ הֲרֵי קָרְבָּנוֹת אֲמוּרִים, הָא מָה אֲנִי מְקַיֵּם וַהֲשִׁמּוֹתִי אֶת מִקְדְּשֵׁיכֶם? מִן הַגְּדוּדִיּוֹת — שַׁיָּרוֹת שֶׁל יִשְׂרָאֵל שֶׁהָיוּ מִתְקַדְּשׁוֹת וְנוֹעָדוֹת לָבֹא שָׁם; הֲרֵי שֶׁבַע פֻּרְעָנֻיּוֹת: אֲכִילַת בְּשַׂר בָּנִים וּבָנוֹת וְהַשְׁמָדַת בָּמוֹת הֲרֵי שְׁתַּיִם — כְּרִיתוּת חַמָּנִים אֵין כָּאן פֻּרְעָנוּת, אֶלָּא עַ"יְ הַשְׁמָדַת הַבִּירָנִיּוֹת יִפְּלוּ הַחַמָּנִים שֶׁבְּרָאשֵׁי הַגַּגּוֹת וְיִכָּרְתוּ — וְנָתַתִּי אֶת פִּגְרֵיכֶם וְגוֹ' הֲרֵי שָׁלוֹשׁ, סִלּוּק שְׁכִינָה אַרְבַּע, חֻרְבַּן עָרִים, שִׁמְמוֹן מִקְדָּשׁ מִן הַגְּדוּדִיּוֹת, וְלֹא אָרִיחַ קָרְבָּנוֹת, הֲרֵי שֶׁבַע:
@30 **והשמתי אני את הארץ.** זוֹ מִדָּה טוֹבָה לְיִשְׂרָאֵל, שֶׁלֹּא יִמְצְאוּ הָאוֹיְבִים נַחַת רוּחַ בְּאַרְצָם, שֶׁתְּהֵא שׁוֹמֵמָה מִיּוֹשְׁבֶיהָ (ספרא):
@31 **ואתכם אזרה בגוים.** זוֹ מִדָּה קָשָׁה, שֶׁבְּשָׁעָה שֶׁבְּנֵי הַמְּדִינָה גּוֹלִים לְמָקוֹם אֶחָד, רוֹאִים זֶה אֶת זֶה וּמִתְנַחֲמִין, וְיִשְׂרָאֵל נִזְרוּ כְבַמְּזָרֶה — כְּאָדָם הַזּוֹרֶה שְׂעוֹרִים בְּנָפָה וְאֵין אַחַת מֵהֶן דְּבוּקָה בַחֲבֶרְתָּהּ (שם):
@31 **והריקתי.** כְּשֶׁשּׁוֹלֵף הַחֶרֶב מִתְרוֹקֵן הַנָּדָן; וּמִדְרָשׁוֹ חֶרֶב הַנִּשְׁמֶטֶת אַחֲרֵיכֶם אֵינָהּ חוֹזֶרֶת מַהֵר, כְּאָדָם שֶׁמֵּרִיק אֶת הַמַּיִם וְאֵין סוֹפָן לַחֲזֹר (ספרא):
@31 **והיתה ארצכם שממה.** שֶׁלֹּא תְמַהֲרוּ לָשׁוּב לְתוֹכָהּ, וּמִתּוֹךְ כָּךְ עָרֵיכֶם יִהְיוּ חָרְבָּה — נִרְאוֹת לָכֶם חֲרֵבוֹת, שֶׁבְּשָׁעָה שֶׁאָדָם גּוֹלֶה מִבֵּיתוֹ וּמִכַּרְמוֹ וּמֵעִירוֹ וְסוֹפוֹ לַחֲזֹר, כְּאִלּוּ אֵין כַּרְמוֹ וּבֵיתוֹ חֲרֵבִים, כָּךְ שְׁנוּיָה בְּתֹ"כֹּ:
@32 **אז תרצה.** תְּפַיֵּס אֶת כַּעַס הַמָּקוֹם שֶׁכָּעַס עַל שְׁמִטּוֹתֶיהָ:
@32 **והרצת.** לַמֶּלֶךְ **את שבתתיה** :
@33 **כל ימי השמה.** לְשׁוֹן הֵעָשׂוֹת, וּמֵ"ם דָּגֵשׁ בִּמְקוֹם כֵּפֶל שְׁמָמָה:
@33 **את אשר לא שבתה.** שִׁבְעִים שָׁנָה שֶׁל גָּלוּת בָּבֶל הֵן הָיוּ כְּנֶגֶד שִׁבְעִים שְׁנוֹת הַשְּׁמִטָּה וְיוֹבֵל שֶׁהָיוּ בַּשָּׁנִים שֶׁהִכְעִיסוּ יִשְׂרָאֵל בְּאַרְצָם לִפְנֵי הַמָּקוֹם — אַרְבַּע מֵאוֹת וּשְׁלוֹשִׁים שָׁנָה; שְׁלוֹשׁ מֵאוֹת וְתִשְׁעִים הָיוּ שְׁנֵי עֲוֹנָם מִשֶּׁנִּכְנְסוּ לָאָרֶץ עַד שֶׁגָּלוּ עֲשֶׂרֶת הַשְּׁבָטִים, וּבְנֵי יְהוּדָה הִכְעִיסוּ לְפָנָיו אַרְבָּעִים שָׁנָה מִשֶּׁגָּלוּ עֲשֶׂרֶת הַשְּׁבָטִים עַד חָרְבוֹת יְרוּשָׁלַיִם, הוּא שֶׁנֶּאֱמַר בִּיחֶזְקֵאל "וְאַתָּה שְׁכַב עַל צִדְּךָ הַשְּׂמָאלִי וְגוֹ', וְכִלִּיתָ אֶת אֵלֶּה וְגוֹ', וְשָׁכַבְתָּ עַל צִדְּךָ הַיְמָנִי אַרְבָּעִים יוֹם וְנָשָׂאתָ אֶת עֲוֹן בֵּית יְהוּדָה", וּנְבוּאָה זוֹ נֶאֶמְרָה לִיחֶזְקֵאל בַּשָּׁנָה הַחֲמִשִּׁית לְגָלוּת הַמֶּלֶךְ יְהוֹיָכִין, וְעוֹד עָשׂוּ שֵׁשׁ שָׁנִים עַד גָּלוּת צִדְקִיָּהוּ, הֲרֵי אַרְבָּעִים וְשֵׁשׁ; וְאִ"תֹּ שְׁנוֹת מְנַשֶּׁה חֲמִשִּׁים וְחָמֵשׁ הָיוּ, מְנַשֶּׁה עָשָֹה תְשׁוּבָה שְׁלוֹשִׁים וְשָׁלוֹשׁ שָׁנָה, וְכָל שְׁנוֹת רִשְׁעוֹ עֶשְֹרִים וּשְׁתַּיִם, כְּמוֹ שֶׁאָמְרוּ בְּאַגָּדַת חֵלֶק, וְשֶׁל אָמוֹן שְׁתַּיִם, וְאַחַת עֶשְֹרֵה לִיהוֹיָקִים, וּכְנֶגְדָּן לְצִדְקִיָּהוּ; צֵא וַחֲשֹׁב לְאַרְבַּע מֵאוֹת וּשְׁלוֹשִׁים וְשֵׁשׁ שָׁנָה שְׁמִטִּין וְיוֹבְלוֹת שֶׁבָּהֶם, וְהֵם שֵׁשׁ עֶשְׂרֶה לְמֵאָה — אַרְבַּע עֶשְׂרֵה שְׁמִטִּין וּשְׁנַיִם יוֹבְלוֹת, הֲרֵי לְאַרְבַּע מֵאוֹת שָׁנָה שִׁשִּׁים וְאַרְבַּע, לִשְׁלוֹשִׁים וְשֵׁשׁ שָׁנָה חָמֵשׁ שְׁמִטּוֹת, הֲרֵי שִׁבְעִים חָסֵר אַחַת, וְעוֹד שָׁנָה יְתֵרָה, שֶׁנִּכְנְסָה בַשְּׁמִטָּה הַמַּשְׁלֶמֶת לְשִׁבְעִים, וַעֲלֵיהֶם נִגְזַר שִׁבְעִים שָׁנָה שְׁלֵמִים, וְכֵן הוּא אוֹמֵר בְּדִבְרֵי הַיָמִים (דברי הימים ב' ל"ו), עַד רָצְתָה הָאָרֶץ אֶת שַׁבְּתוֹתֶיהָ … לְמַלֹּאות שִׁבְעִים שָׁנָה (סדר עולם):
@34 **והבאתי מרך.** פַּחַד וְרֹךְ לֵבָב; מ"ם שֶׁל מֹרֶךְ יְסוֹד נוֹפֵל הוּא, כְּמוֹ מ"ם שֶׁל מוֹעֵד וְשֶׁל מוֹקֵשׁ:
@34 **ונסו מנסת חרב.** כְּאִלּוּ רוֹדְפִים הוֹרְגִים אוֹתָם:
@34 **עלה נדף.** שֶׁהָרוּחַ דּוֹחֲפוֹ וּמַכֵּהוּ עַל עָלֶה אַחֵר וּמְקַשְׁקֵשׁ וּמוֹצִיא קוֹל, וְכֵן תַּרְגּוּמוֹ קַל טַרְפָּא דְשָׁקִיף, לְשׁוֹן חֲבָטָה, "שְׁדוּפוֹת קָדִים" (בראשית מ"א) — שְׁקִיפָן קִדּוּם, לְשׁוֹן מַשְׁקוֹף, מְקוֹם חֲבָטַת הַדֶּלֶת, וְכֵן תַּרְגּוּמוֹ שֶׁל "חַבּוּרָה" (שמות כ"א) — מַשְׁקוֹפֵי:
@35 **וכשלו איש באחיו.** כְּשֶׁיָּרוּצוּ לָנוּס יִכָּשְׁלוּ זֶה בָזֶה, כִּי יִבָּהֲלוּ לָרוּץ:
@35 **כמפני חרב.** כְּאִלּוּ בּוֹרְחִים מִלִּפְנֵי הוֹרְגִים, שֶׁיְּהֵא בִלְבָבָם פַּחַד, וְכָל שָׁעָה סְבוּרִים שֶׁאָדָם רוֹדְפָם; וּמִדְרָשׁוֹ וְכָשְׁלוּ אִישׁ בְּאָחִיו, זֶה נִכְשָׁל בַּעֲוֹנוֹ שֶׁל זֶה, שֶׁכָּל יִשְׂרָאֵל עֲרֵבִין זֶה לָזֶה (ספרא; סנהדרין כ"ז):
@36 **ואבדתם בגוים.** כְּשֶׁתִּהְיוּ פְזוּרִים, תִּהְיוּ אֲבוּדִים זֶה מִזֶּה (עי' ספרא):
@36 **ואכלה אתכם.** אֵלּוּ הַמֵּתִים בַּגּוֹלָה:
@37 **בעונת אבתם אתם.** כְּשֶׁעֲווֹנוֹת אֲבוֹתָם אִתָּם — כְּשֶׁאוֹחֲזִים מַעֲשֵׂה אֲבוֹתֵיהֶם בִּידֵיהֶם (שם):
@37 **ימקו.** לְשׁוֹן הֲמַסָּה, כְּמוֹ יִמַּסּוּ, וְכָמוֹהוּ "תִּמַּקְנָה בְחֹרֵיהֶן" (זכריה י"ד), "נָמַקּוּ חַבּוּרֹתָי" (תהילים ל"ח):
@39 **והבאתי אתם.** אֲנִי בְעַצְמִי אֲבִיאֵם; זוֹ מִדָּה טוֹבָה לְיִשְׂרָאֵל, שֶׁלֹּא יִהְיוּ אוֹמְרִים, הוֹאִיל וְגָלִינוּ בֵּין הָאֻמּוֹת נַעֲשֶׂה כְמַעֲשֵׂיהֶם, אֲנִי אֵינִי מַנִּיחָם, אֶלָּא מַעֲמִיד אֲנִי אֶת נְבִיאַי וּמַחֲזִירָן לְתַחַת כְּנָפַי, שֶׁנֶּאֱמַר (יחזקאל כ"א), "וְהָעֹלָה עַל רוּחֲכֶם הָיוֹ לֹא תִהְיֶה וְגוֹ' חַי אָנִי … אִם לֹא בְּיָד חֲזָקָה וְגוֹ'" (ספרא):
@39 **או אז יכנע.** כְּמוֹ "אוֹ נוֹדַע כִּי שׁוֹר נַגָּח הוּא" (שמות כ"א) — אִם אָז יִכָּנַע; לָשׁוֹן אַחֵר אוּלַי — שֶׁמָּא אָז יִכָּנַע לְבָבָם וְגוֹ':
@39 **ואז ירצו את עונם.** יְכַפְּרוּ עַל עֲווֹנָם בְּיִסּוּרֵיהֶם:
@40 **וזכרתי את בריתי יעקוב.** בַּחֲמִשָּׁה מְקוֹמוֹת נִכְתַּב מָלֵא, וְאֵלִיָּהוּ חָסֵר בַּחֲמִשָּׁה מְקוֹמוֹת — יַעֲקֹב נָטַל אוֹת מִשְּׁמוֹ שֶׁל אֵלִיָּהוּ עֵרָבוֹן שֶׁיָּבֹא וִיבַשֵּׂר גְּאֻלַּת בָּנָיו:
@40 **וזכרתי את בריתי יעקוב.** לָמָּה נִמְנוּ אֲחוֹרַנִּית? כְּלוֹמַר, כְּדַאי הוּא יַעֲקֹב הַקָּטָן לְכָךְ, וְאִם אֵינוֹ כְדַאי, הֲרֵי יִצְחָק עִמּוֹ, וְאִם אֵינוֹ כְדַאי, הֲרֵי אַבְרָהָם עִמּוֹ שֶׁהוּא כְדַאי, וְלָמָּה לֹא נֶאֶמְרָה זְכִירָה בְיִצְחָק? אֶלָּא אֲפָרוֹ שֶׁל יִצְחָק נִרְאֶה לְפָנַי צָבוּר וּמֻנָּח עַל הַמִּזְבֵּחַ (ספרא):
@41 **יען וביען.** גְּמוּל וּבִגְמוּל אֲשֶׁר בְּמִשְׁפָּטַי מָאָסוּ (עי' ספרא):
@42 **ואף גם זאת.** וְאַף אֲפִלּוּ אֲנִי עוֹשֶׂה עִמָּהֶם זֹאת הַפֻּרְעָנוּת אֲשֶׁר אָמַרְתִּי **בהיותם בארץ איביהם** , לֹא אֶמְאָסֵם לְכַלֹּתָם וּלְהָפֵר בְּרִיתִי אֲשֶׁר אִתָּם:
@43 **ברית ראשנים.** שֶׁל שְׁבָטִים (ספרא):
@44 **והתורת.** אַחַת בִּכְתָב וְאַחַת בְּעַל פֶּה, מַגִּיד שֶׁכֻּלָּם נִתְּנוּ לְמֹשֶׁה בְּסִינַי (שם):
@46 **כי יפלא.** יַפְרִישׁ בְּפִיו:
@46 **בערכך נפשת.** לִתֵּן עֵרֶךְ נְפָשׁוֹת — לוֹמַר עֵרֶךְ דָּבָר שֶׁנַּפְשׁוֹ תְלוּיָה בוֹ עָלַי (עי' ספרא; ערכין ד'):
@47 **והיה ערכך וגו'.** אֵין עֵרֶךְ זֶה לְשׁוֹן דָּמִים, אֶלָּא בֵּין שֶׁהוּא יָקָר בֵּין שֶׁהוּא זוֹל, כְּפִי שָׁנָיו הוּא הָעֵרֶךְ הַקָּצוּב עָלָיו בְּפָרָשָׁה זוֹ:
@47 **ערכך.** כְּמוֹ עֵרֶךְ, וְכֵפֶל הַכָּפִי"ן לֹא יָדַעְתִּי מֵאֵיזֶה לָשׁוֹן הוּא:
@49 **ואם מבן חמש שנים.** לֹא שֶׁיְּהֵא הַנּוֹדֵר קָטָן — שֶׁאֵין בְּדִבְרֵי קָטָן כְּלוּם — אֶלָּא גָּדוֹל שֶׁאָמַר עֵרֶךְ קָטָן זֶה שֶׁהוּא בֶן חָמֵשׁ שָׁנִים עָלַי (עי' ערכין ב'):
@51 **ואם מבן ששים שנה וגו'.** כְּשֶׁמַּגִּיעַ לִימֵי הַזִּקְנָה, הָאִשָּׁה קְרוֹבָה לְהֵחָשֵׁב כְּאִישׁ, לְפִיכָךְ הָאִישׁ פּוֹחֵת בְּהִזְדַּקְּנוֹ יוֹתֵר מִשְּׁלִישׁ בְּעֶרְכּוֹ, וְהָאִשָּׁה אֵינָהּ פוֹחֶתֶת אֶלָּא שְׁלִישׁ בְּעֶרְכָּהּ, דְּאָמְרֵי אִינְשֵׁי "סָבָא בְּבֵיתָא, פַּחָא בְּבֵיתָא, סָבְתָא בְּבֵיתָא סִימָא בְּבֵיתָא וְסִימָנָא טָבָא בְּבֵיתָא" (ערכין י"ט):
@52 **ואם מך הוא.** שֶׁאֵין יָדוֹ מַשֶּׂגֶת לִתֵּן הָעֵרֶךְ הַזֶּה.
@52 **והעמידו.** לַנֶּעֱרָךְ לִפְנֵי הַכֹּהֵן, וְיַעֲרִיכֶנּוּ לְפִי הַשָּׂגַת יָדוֹ שֶׁל מַעֲרִיךְ:
@52 **על פי אשר תשיג.** לְפִי מַה שֶּׁיֶּשׁ לוֹ יְסַדְּרֶנּוּ, וְיַשְׁאִיר לוֹ כְּדֵי חַיָּיו: מִטָּה, כַּר וְכֶסֶת, וּכְלֵי אֻמָּנוּת; אִם הָיָה חַמָּר מַשְׁאִיר לוֹ חֲמוֹרוֹ (בבא מציעא קי"ד; ערכין כ"ג):
@53 **כל אשר יתן ממנו.** אָמַר רַגְלָהּ שֶׁל זוֹ עוֹלָה, דְּבָרָיו קַיָּמִין, וְתִמָּכֵר לְצָרְכֵי עוֹלָה, וְדָמֶיהָ חֻלִּין חוּץ מִדְּמֵי אוֹתוֹ הָאֵבֶר (ספרא; ערכין ה'):
@54 **טוב ברע.** תָּם בְּבַעַל מוּם.
@54 **או רע בטוב.** וְכָל שֶׁכֵּן טוֹב בְּטוֹב וְרַע בְּרַע (עי' תמורה ט'):
@55 **ואם כל בהמה טמאה.** בְּבַעֲלַת מוּם הַכָּתוּב מְדַבֵּר, שֶׁהִיא טְמֵאָה לְהַקְרָבָה, וְלִמֶּדְךָ הַכָּתוּב שֶׁאֵין קָדָשִׁים תְּמִימִים יוֹצְאִין לְחֻלִּין בְּפִדְיוֹן אֶלָּא אִם כֵּן הֻמְּמוּ (שם ל"ג):
@56 **כערכך הכהן כן יהיה.** לִשְׁאָר כָּל אָדָם הַבָּא לִקְנוֹתָהּ מִיַּד הֶקְדֵּשׁ:
@57 **ואם גאל יגאלנה.** בַּבְּעָלִים הֶחֱמִיר הַכָּתוּב לְהוֹסִיף חֹמֶשׁ, וְכֵן בְּמַקְדִּישׁ בַּיִת, וְכֵן בְּמַקְדִּישׁ אֶת הַשָּׂדֶה, וְכֵן בְּפִדְיוֹן מַעֲשֵֹר שֵׁנִי — הַבְּעָלִים מוֹסִיפִין חֹמֶשׁ וְלֹא שְׁאָר כָּל אָדָם (שם כ"ה):
@60 **והיה ערכך לפי זרעו.** לֹא כְּפִי שָׁוְיָהּ, אַחַת שָׂדֶה טוֹבָה וְאַחַת שָׂדֶה רָעָה פִּדְיוֹן הֶקְדֵּשָׁן שָׁוֶה — בֵּית כֹּר שְׂעוֹרִים בַּחֲמִשִּׁים שְׁקָלִים — כָּךְ גְּזֵרַת הַכָּתוּב, וְהוּא שֶׁבָּא לְגָאֳלָהּ בִּתְחִלַּת הַיּוֹבֵל. וְאִם בָּא לְגָאֳלָהּ בְאֶמְצָעוֹ, נוֹתֵן לְפִי הַחֶשְׁבּוֹן סֶלַע וּפֻנְדְּיוֹן לְשָׁנָה, לְפִי שֶׁאֵינָהּ הֶקְדֵּשׁ אֶלָּא לְמִנְיַן שְׁנוֹת הַיּוֹבֵל, שֶׁאִם נִגְאֲלָה הֲרֵי טוֹב, וְאִם לָאו הַגִּזְבָּר מוֹכְרָהּ בַּדָּמִים הַלָּלוּ לְאַחֵר, וְעוֹמֶדֶת בְּיַד הַלּוֹקֵחַ עַד הַיּוֹבֵל כִּשְׁאָר כָּל הַשָּׂדוֹת הַמְּכוּרוֹת, וּכְשֶׁהִיא יוֹצְאָה מִיָּדוֹ חוֹזֶרֶת לַכֹּהֲנִים שֶׁל אוֹתוֹ מִשְׁמָר שֶׁהַיּוֹבֵל פּוֹגֵעַ בּוֹ, וּמִתְחַלֶּקֶת בֵּינֵיהֶם, זֶהוּ הַמִּשְׁפָּט הָאָמוּר בְּמַקְדִּישׁ שָׂדֶה, וְעַכְשָׁו אֲפָרְשֶׁנּוּ עַל סֵדֶר הַמִּקְרָאוֹת:
@61 **אם משנת היבל יקדיש וגו'.** אִם מִשֶּׁעָבְרָה שְׁנַת הַיּוֹבֵל מִיָּד הִקְדִּישָׁהּ, וּבָא זֶה לְגָאֳלָהּ מִיָּד.
@61 **כערכך יקום.** כָּעֵרֶךְ הַזֶּה הָאָמוּר יִהְיֶה — חֲמִשִּׁים כֶּסֶף יִתֵּן:
@62 **ואם אחר היבל יקדיש.** וְכֵן אִם הִקְדִּישָׁהּ מִשְּׁנַת הַיֹּבֵל וְנִשְׁתַּהָת בְּיַד גִּזְבָּר, וּבָא זֶה לְגָאֳלָהּ אַחַר הַיּוֹבֵל.
@62 **וחשב לו הכהן את הכסף על פי השנים הנותרת.** כְּפִי חֶשְׁבּוֹן; כֵּיצַד? הֲרֵי קָצַב דָּמֶיהָ שֶׁל אַרְבָּעִים וְתֵשַׁע שָׁנָה חֲמִשִּׁים שֶׁקֶל, הֲרֵי שֶׁקֶל לְכָל שָׁנָה וְשֶׁקֶל יָתֵר עַל כֻּלָּן, וְהַשֶּׁקֶל אַרְבָּעִים וּשְׁמוֹנָה פֻנְדְּיוֹן, הֲרֵי סֶלַע וּפֻנְדְּיוֹן לְשָׁנָה, אֶלָּא שֶׁחָסֵר פֻּנְדְּיוֹן אֶחָד לְכֻלָּן, וְאָמְרוּ רַבּוֹתֵינוּ שֶׁאוֹתוֹ פֻּנְדְּיוֹן קַלְבּוֹן לִפְרוֹטְרוֹט, וְהַבָּא לִגְאֹל, יִתֵּן סֶלַע וּפֻנְדְּיוֹן לְכָל שָׁנָה לַשָּׁנִים הַנּוֹתָרוֹת עַד שְׁנַת הַיּוֹבֵל (עי' ספרא; ערכין כ"ד):
@62 **ונגרע מערכך.** מִנְיַן הַשָּׁנִים שֶׁמִּשְּׁנַת הַיּוֹבֵל עַד שְׁנַת הַפִּדְיוֹן:
@63 **ואם גאל יגאל.** הַמַּקְדִּישׁ אוֹתוֹ, יוֹסִיף חֹמֶשׁ עַל הַקִּצְבָּה הַזֹּאת:
@64 **ואם לא יגאל את השדה.** הַמַּקְדִּישׁ:
@64 **ואם מכר.** הַגִּזְבָּר:
@64 **את השדה לאיש אחר לא יגאל עוד.** לָשׁוּב בְּיַד הַמַּקְדִּישׁ:
@65 **והיה השדה בצאתו ביבל.** מִיַּד הַלּוֹקְחוֹ מִן הַגִּזְבָּר, כְּדֶרֶךְ שְׁאָר שָׂדוֹת הַיּוֹצְאוֹת מִיַּד לוֹקְחֵיהֶם בַּיּוֹבֵל:
@65 **קדש לה'.** לֹא שֶׁיָּשׁוּב לְהֶקְדֵּשׁ בֶּדֶק הַבַּיִת, לְיַד הַגִּזְבָּר, אֶלָּא **כשדה החרם** הַנָּתוּן לַכֹּהֲנִים — שֶׁנֶּאֱמַר "כָּל חֵרֶם בְּיִשְׂרָאֵל לְךָ יִהְיֶה" (במדבר י"ח) — אַף זוֹ תִּתְחַלֵּק לַכֹּהֲנִים שֶׁל אוֹתוֹ מִשְׁמָר שֶׁיּוֹם הַכִּפּוּרִים שֶׁל יוֹבֵל פּוֹגֵעַ בּוֹ (ערכין כ"ח):
@66 **ואם את שדה מקנתו וגו'.** חִלּוּק יֵשׁ בֵּין שְׂדֵה מִקְנָה לִשְׂדֵה אֲחֻזָּה, שֶׁשְּׂדֵה מִקְנָה לֹא תִתְחַלֵּק לַכֹּהֲנִים בַּיּוֹבֵל, לְפִי שֶׁאֵינוֹ יָכוֹל לְהַקְדִּישָׁהּ אֶלָּא עַד הַיּוֹבֵל, שֶׁהֲרֵי בַיּוֹבֵל הָיְתָה עֲתִידָה לָצֵאת מִיָּדוֹ וְלָשׁוּב לַבְּעָלִים, לְפִיכָךְ אִם בָּא לְגָאֳלָהּ, יִגְאַל בַּדָּמִים הַלָּלוּ הַקְּצוּבִים לִשְׂדֵה אֲחֻזָּה; וְאִם לֹא יִגְאַל, וְיִמְכְּרֶנָּה גִּזְבָּר לְאַחֵר, אוֹ אִם יִגְאַל הוּא **בשנת היובל ישוב השדה לאשר קנהו מאתו** — אוֹתוֹ שֶׁהִקְדִּישׁ, וּפֶן תֹּאמַר "לַאֲשֶׁר קָנָהוּ" הַלּוֹקֵחַ הַזֶּה הָאַחֲרוֹן מֵאִתּוֹ, וְזֶהוּ הַגִּזְבָּר, לְכָךְ הֻצְרַךְ לוֹמַר **לאשר לו אחזת הארץ** — מִירֻשַּׁת אָבוֹת, וְזֶהוּ בְּעָלִים הָרִאשׁוֹנִים שֶׁמְּכָרוּהָ לַמַּקְדִּישׁ (ערכין כ"ו):
@69 **וכל ערכך יהיה בשקל הקדש.** כָּל עֶרְכְּךָ שֶׁכָּתוּב בּוֹ שְׁקָלִים, יִהְיֶה בְשֶׁקֶל הַקֹּדֶשׁ:
@69 **עשרים גרה.** עֶשְׂרִים מָעוֹת, כָּךְ הָיוּ מִתְּחִלָּה, וּלְאַחַר מִכָּאן הוֹסִיפוּ שְׁתוּת, וְאָמְרוּ רַבּוֹתֵינוּ שֵׁשׁ מָעָה כֶּסֶף דִּינָר, עֶשְׂרִים וְאַרְבַּע מָעוֹת לְסֶלַע (עי' בכורות נ'):
@70 **לא יקדיש איש אתו.** לְשֵׁם קָרְבָּן אַחֵר, לְפִי שֶׁאֵינוֹ שֶׁלּוֹ (עי' ערכין כ"ט):
@71 **ואם בבהמה הטמאה וגו'.** אֵין הַמִּקְרָא הַזֶּה מוּסָב עַל הַבְּכוֹר, שֶׁאֵין לוֹמַר בִּבְכוֹר בְּהֵמָה טְמֵאָה וּפָדָה בְּעֶרְכְּךָ, וַחֲמוֹר אֵין זֶה, שֶׁהֲרֵי אֵין פִּדְיוֹן פֶּטֶר חֲמוֹר אֶלָּא טָלֶה, וְהוּא מַתָּנָה לַכֹּהֵן, וְאֵינוֹ לְהֶקְדֵּשׁ, אֶלָּא הַכָּתוּב מוּסָב עַל הַהֶקְדֵּשׁ, שֶׁהַכָּתוּב שֶׁל מַעְלָה דִּבֵּר בְּפִדְיוֹן בְּהֵמָה טְהוֹרָה שֶׁהֻמְּמָה, וְכָאן דִּבֵּר בְּמַקְדִּישׁ בְּהֵמָה טְמֵאָה לְבֶדֶק הַבַּיִת:
@71 **ופדה בערכך.** כְּפִי מַה שֶּׁיַּעֲרִיכֶנָּה הַכֹּהֵן:
@71 **ואם לא יגאל.** עַל יְדֵי בְעָלִים:
@71 **ונמכר בערכך.** לַאֲחֵרִים:
@72 **אך כל חרם וגו'.** נֶחְלְקוּ רַבּוֹתֵינוּ בַּדָּבָר, יֵ"אֹ סְתָם חֲרָמִים לְהֶקְדֵּשׁ, וּמָה אֲנִי מְקַיֵּם כָּל חֵרֶם בְּיִשְׂרָאֵל לְךָ יִהְיֶה? בְּחֶרְמֵי כֹהֲנִים, שֶׁפֵּרֵשׁ וְאָמַר הֲרֵי זֶה חֵרֶם לַכֹּהֵן; וְיֵשׁ שֶׁאָמְרוּ, סְתָם חֲרָמִים לַכֹּהֵן (עי' ספרא; ערכין כ"ח):
@72 **לא ימכר ולא יגאל.** אֶלָּא יִנָּתֵן לַכֹּהֵן: לְדִבְרֵי הָאוֹמֵר סְתָם חֲרָמִים לַכֹּהֲנִים, מְפֹרָשׁ מִקְרָא זֶה בִּסְתָם חֲרָמִים, וְהָאוֹמֵר סְתָם חֲרָמִים לְבֶדֶק הַבַּיִת, מְפָרֵשׁ מִקְרָא זֶה בְּחֶרְמֵי כֹהֲנִים — שֶׁהַכֹּל מוֹדִים שֶׁחֶרְמֵי כֹהֲנִים אֵין לָהֶם פִּדְיוֹן עַד שֶׁיָּבֹאוּ לְיַד כֹּהֵן וְחֶרְמֵי גָּבוֹהַּ נִפְדִּים:
@72 **כל חרם קדש קדשים הוא.** הָאוֹמֵר סְתָם חֲרָמִים לְבֶדֶק הַבַּיִת, מֵבִיא רְאָיָה מִכָּאן, וְהָאוֹמֵר סְתָם חֲרָמִים לַכֹּהֲנִים, מְפָרֵשׁ "כָּל חֵרֶם קֹדֶשׁ קָדָשִׁים הוּא" לְלַמֵּד שֶׁחֶרְמֵי כֹהֲנִים חָלִים עַל קָדְשֵׁי קָדָשִׁים וְעַל קָדָשִׁים קַלִּים, וְנוֹתֵן לַכֹּהֵן, כְּמוֹ שֶׁשָּׁנִינוּ בְמַסֶּכֶת עֲרָכִין (דף כ"ח), אִם נֵדֶר, נוֹתֵן דְּמֵיהֶן, וְאִם נְדָבָה, נוֹתֵן אֶת טוֹבָתָהּ:
@72 **מאדם.** כְּגוֹן שֶׁהֶחֱרִים עֲבָדָיו וְשִׁפְחוֹתָיו הַכְּנַעֲנִים:
@73 **כל חרם אשר יחרם וגו'.** הַיּוֹצֵא לֵהָרֵג וְאָמַר אֶחָד עֶרְכּוֹ עָלַי, לֹא אָמַר כְּלוּם (ספרא; ערכין ו'):
@73 **מות יומת.** הֲרֵי הוֹלֵךְ לָמוּת, לְפִיכָךְ לֹא יִפָּדֶה — אֵין לוֹ לֹא דָמִים וְלֹא עֵרֶךְ:
@74 **וכל מעשר הארץ.** בְּמַעֲשֵׂר שֵׁנִי הַכָּתוּב מְדַבֵּר:
@74 **מזרע הארץ.** דָּגָן:
@74 **מפרי העץ.** תִּירוֹשׁ וְיִצְהָר:
@74 **לה' הוא.** קְנָאוֹ הַשֵּׁם. וּמִשֻּׁלְחָנוֹ צִוָּה לְךָ לַעֲלוֹת וְלֶאֱכֹל בִּירוּשָׁלַיִם, כְּמוֹ שֶׁנֶּאֱמַר (דברים י"ד), וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ, מַעְשַׂר דְּגָנְךָ תִּירֹשְׁךָ וְגוֹ' (עי' קידושין נ"ד):
@75 **ממעשרו.** וְלֹא מִמַּעְשַׂר חֲבֵרוֹ — הַפּוֹדֶה מַעֲשֵׂר שֶׁל חֲבֵרוֹ אֵין מוֹסִיף חֹמֶשׁ, וּמַה הִיא גְאֻלָּתוֹ? יִפְדֶנּוּ כְּדֵי לְהַתִּירוֹ בַאֲכִילָה בְכָל מָקוֹם, וְהַמָּעוֹת יַעֲלֶה וְיֹאכַל בִירוּשָׁלַיִם, כְּמוֹ שֶׁנֶּאֱמַר (דברים י"ד), וְנָתַתָּה בַּכָּסֶף וְגוֹ' (עי' קידושין כ"ד):
@76 **תחת השבט.** כְּשֶׁבָּא לְעַשְּׂרָן, מוֹצִיאָן בַּפֶּתַח זֶה אַחַר זֶה, וְהָעֲשִֹירִי מַכֶּה בְּשֵׁבֶט צְבוּעָה בְסִקְרָא, לִהְיוֹת נִכָּר שֶׁהוּא מַעֲשֵׂר, כֵּן עוֹשֶׂה לִטְלָאִים וְלַעֲגָלִים שֶׁל כָּל שָׁנָה וְשָׁנָה (בכו' נ"ח):
@76 **יהיה קדש.** לִקְרַב לַמִּזְבֵּחַ דָּמוֹ וְאֵמוּרָיו, וְהַבָּשָׂר נֶאֱכָל לַבְּעָלִים, שֶׁהֲרֵי לֹא נִמְנָה עִם שְׁאָר מַתְּנוֹת כְּהֻנָה, וְלֹא מָצִינוּ שֶׁיְּהֵא נָתוּן בְּשָׂרוֹ לַכֹּהֲנִים:
@77 **לא יבקר וגו'.** לְפִי שֶׁנֶּאֱמַר "וְכֹל מִבְחַר נִדְרֵיכֶם" (דברים י"ב), יָכוֹל יְהֵא בוֹרֵר וּמוֹצִיא אֶת הַיָּפֶה, תַּ"לֹ "לֹא יְבַקֵּר בֵּין טוֹב לָרַע" — בֵּין תָּם בֵּין בַּעַל מוּם חָלָה עָלָיו קְדֻשָּׁה — וְלֹא שֶׁיִּקְרַב בַּעַל מוּם, אֶלָּא יֵאָכֵל בְּתוֹרַת מַעֲשֵׂר וְאָסוּר לִגָּזֵז וְלֵעָבֵד (עי' בכורות י"ד):

@2 **וְנָתַתִּי גִשְׁמֵיכֶם בְּעִתָּם** הִקְדִּים דְּבַר הַגְּשָׁמִים כִּי בְּבוֹאָם בְּעִתָּם כַּאֲשֶׁר יָאוּת יִהְיֶה הָאֲוִיר זַךְ וְטוֹב וְהַמַּעְיָנוֹת וְהַנְּהָרוֹת טוֹבִים, וְיִהְיֶה זֶה סִבַּת בְּרִיאוּת לַגּוּפִים, וְהַפֵּרוֹת כֻּלָּם יִרְבּוּ וְיִתְבָּרְכוּ בָּהֶן, כַּאֲשֶׁר יֹאמַר "וְנָתְנָה הָאָרֶץ יְבוּלָהּ וְעֵץ הַשָּׂדֶה יִתֵּן פִּרְיוֹ". וְהִנֵּה עִם זֶה לֹא יֶחֱלֶה הָאָדָם וְלֹא יִהְיֶה בָּהֶם מְשַׁכֵּלָה וַעֲקָרָה וּבִבְהֶמְתָּם וְיִמְלְאוּ יְמֵיהֶם, כִּי בִּהְיוֹת הַגּוּפִים גְּדוֹלִים וּבְרִיאִים יִתְקַיְּמוּ כִּימֵי הָאָדָם, וְהִנֵּה הִיא גְּדוֹלָה שֶׁבַּבְּרָכוֹת. וְהִנֵּה אָמַר כִּי הַשָּׁמַיִם יַעֲנוּ אֶת הָאָרֶץ בִּגְשָׁמִים בְּעִתָּם, וְהָאָרֶץ תַּעֲנֶה אֶת יְבוּלָהּ וְהִיא הַצֶּמַח וּבַעֲלֵי נֶפֶשׁ הַתְּנוּעָה בְּהֵמָה וְחַיָּה וְרֶמֶשׂ וְעוֹף גַּם הַדָּגִים, כִּי הָאָרֶץ תִּכְלֹל הַכַּדּוּר הַתַּחְתּוֹן כֻּלּוֹ, כְּמוֹ "בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ" (בראשית א א), "וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ" (שם ב א), וְכֵן "הַלְלוּ אֶת ה' מִן הָאָרֶץ תַּנִּינִים וְכָל תְּהֹמוֹת" (תהלים קמח ז), וְכֵן בְּרוֹב מְקוֹמוֹת הַכָּתוּב. וְהִנֵּה כָּל הַתּוֹלָדוֹת שֶׁבַּתַּחְתּוֹנִים יְבוּל הָאָרֶץ:
@4 **וְנָתַתִּי שָׁלוֹם בָּאָרֶץ** שֶׁיִּהְיֶה שָׁלוֹם בֵּינֵיכֶם וְלֹא תִּלָּחֲמוּ אִישׁ בְּאָחִיו, אוֹ הַשָּׁלוֹם הוּא שֶׁיַּשְׁבִּית חַיָּה רָעָה מִן הָאָרֶץ וְהַחֶרֶב לֹא תַּעֲבֹר בְּאַרְצְכֶם כְּלָל, אֲבָל אַתֶּם תִּרְדְּפוּ אֶת אוֹיְבֵיכֶם לָצֵאת אֲלֵיהֶם לַמִּלְחָמָה וְיָנוּסוּ. וְעַל דֶּרֶךְ הָאֱמֶת, שֶׁיִּתֵּן הַשָּׁלוֹם מְחֻבָּר בָּאָרֶץ, וְהוּא שְׁלוֹם הַכֹּל הַשָּׁקוּל כְּנֶגֶד הַכֹּל:
@4 **וְהִשְׁבַּתִּי חַיָּה רָעָה מִן הָאָרֶץ** עַל דַּעַת ר' יְהוּדָה שֶׁאָמַר מַעֲבִירָן מִן הָעוֹלָם (תו"כ פרק ב א), הוּא כִּפְשׁוּטוֹ, שֶׁלֹּא יָבוֹאוּ חַיּוֹת רָעוֹת בְּאַרְצָם, כִּי בִּהְיוֹת הַשָּׂבָע וּבִרְבוֹת הַטּוֹבָה וֶהֱיוֹת הֶעָרִים מְלֵאוֹת אָדָם לֹא תָּבֹאנָה חַיּוֹת בַּיִּשּׁוּב. וְעַל דַּעַת רַבִּי שִׁמְעוֹן שֶׁאָמַר מַשְׁבִּיתָן שֶׁלֹּא יַזִּיקוּ (שם), יֹאמַר וְהִשְׁבַּתִּי רָעַת הַחַיּוֹת מִן הָאָרֶץ, וְהוּא הַנָּכוֹן, כִּי תִהְיֶה אֶרֶץ יִשְׂרָאֵל בְּעֵת קִיּוּם הַמִּצְוֹת כַּאֲשֶׁר הָיָה הָעוֹלָם מִתְּחִלָּתוֹ קֹדֶם חֶטְאוֹ שֶׁל אָדָם הָרִאשׁוֹן, אֵין חַיָּה וָרֶמֶשׂ מֵמִית אָדָם, וּכְמוֹ שֶׁאָמְרוּ (ברכות לג), אֵין עַרְוָד מֵמִית אֶלָּא חֵטְא מֵמִית. וְזֶה שֶׁאָמַר הַכָּתוּב "וְשִׁעֲשַׁע יוֹנֵק עַל חֻר פָּתֶן" (ישעיהו יא ח), וְכֵן "וּפָרָה וָדֹב תִּרְעֶינָה וְאַרְיֵה כַּבָּקָר יֹאכַל תֶּבֶן" (שם פסוק ז), כִּי לֹא הָיָה הַטֶּרֶף בַּחַיּוֹת הָרָעוֹת רַק מִפְּנֵי חֶטְאוֹ שֶׁל אָדָם, כִּי נִגְזַר עָלָיו לִהְיוֹת טֶרֶף לְשִׁנֵּיהֶם, וְהוּשַׂם הַטֶּרֶף טֶבַע לָהֶם גַּם לִטְרֹף זוֹ אֶת זוֹ כַּיָּדוּעַ כִּי בְּטָרְפָם הָאָדָם פַּעַם אַחַת יוֹסִיפוּ לִהְיוֹת רָעִים יוֹתֵר, וְכֵן אָמַר הַכָּתוּב "וַיִּלְמַד לִטְרָף טֶרֶף אָדָם אָכָל" (יחזקאל יט ג). וְהִנֵּה בִּבְרִיאָתוֹ שֶׁל עוֹלָם נֶאֱמַר בַּחַיּוֹת שֶׁנָּתַן לָהֶם הָעֵשֶׂב לְאָכְלָה, דִּכְתִיב "וּלְכָל חַיַּת הָאָרֶץ וּלְכָל עוֹף הַשָּׁמַיִם וּלְכֹל רוֹמֵשׂ עַל הָאָרֶץ אֲשֶׁר בּוֹ נֶפֶשׁ חַיָּה אֶת כָּל יֶרֶק עֵשֶׂב לְאָכְלָה" (בראשית א ל), וְאָמַר הַכָּתוּב "וַיְהִי כֵן", כִּי הוּא הַטֶּבַע אֲשֶׁר הוּשַׂם בָּהֶם לָעַד, וְאַחַר כָּךְ לָמְדוּ הַטֶּרֶף מִפְּנֵי הַחֵטְא הַמֵּמִית כַּאֲשֶׁר פֵּרַשְׁתִּי, וּכְשֶׁהֻתַּר שְׁחִיטַת בַּעֲלֵי הַחַיִּים לִבְנֵי נֹחַ אַחֲרֵי הַמַּבּוּל, וְהִזְהִיר עַל הָאָדָם (שם ט ה), "וְאַךְ אֶת דִּמְכֶם לְנַפְשֹׁתֵיכֶם אֶדְרֹשׁ וְגוֹ' אֶת נֶפֶשׁ הָאָדָם" וְלֹא נֶפֶשׁ חַיָּה מִיַּד חַיָּה בַּחֲבֶרְתָּהּ, נִשְׁאֲרוּ עַל מִנְהָגָם לִטְרֹף. וּבִהְיוֹת אֶרֶץ יִשְׂרָאֵל עַל הַשְּׁלֵמוּת תִּשְׁבֹּת רָעַת מִנְהָגָם וְיַעַמְדוּ עַל הַטֶּבַע הָרִאשׁוֹן אֲשֶׁר הוּשַׁם בָּהֶם בְּעֵת יְצִירָתָם. וּכְבָר הִזְכַּרְתִּי מִזֶּה בְּסֵדֶר תּוֹלְדוֹת נֹחַ (בראשית ט ו). וְעַל כֵּן אָמַר הַכָּתוּב עַל יְמֵי הַגּוֹאֵל הַיּוֹצֵא מִגֶּזַע יִשַׁי שֶׁיָּשׁוּב הַשָּׁלוֹם בָּעוֹלָם, וְיֶחְדַּל הַטֶּרֶף וְרָעַת הַבְּהֵמָה וְכָל הָרֶמֶשׂ כַּאֲשֶׁר הָיָה בְּטִבְעָם מִתְּחִלָּה. וְהַכַּוָּנָה הָיְתָה בּוֹ עַל חִזְקִיָּהוּ, שֶׁבִּקֵּשׁ הקב"ה לַעֲשׂוֹתוֹ מָשִׁיחַ (סנהדרין צד) וְלֹא עָלְתָה זְכוּתָם לְכָךְ, וְיִהְיֶה הַמַּעֲשֶׂה עַל הַמָּשִׁיחַ הֶעָתִיד לָבֹא:
@6 **וְנָפְלוּ אֹיְבֵיכֶם לִפְנֵיכֶם לֶחָרֶב** הִבְטִיחַ תְּחִלָּה (ויקרא כ"ו:ז') כִּי יִרְדְּפוּ אֶת אוֹיְבֵיהֶם וְיִפְּלוּ בְּחַרְבָּם, וְחָזַר וְכָפַל "וְנָפְלוּ אֹיְבֵיכֶם לִפְנֵיכֶם לֶחָרֶב", שֶׁיִּתֵּן לָהֶם אֹמֶץ לֵב וּגְבוּרָה לִרְדֹּף חֲמִשָּׁה מֵאָה, וְיִתֵּן מֹרֶךְ בְּלֵב הָאוֹיְבִים שֶׁיָּנוּסוּ מֵאָה מִפְּנֵי חֲמִשָּׁה וְיִפְּלוּ כֻּלָּם בְּחֶרֶב הַחֲמִשָּׁה, כִּי יִתָּכֵן שֶׁיָּנוּסוּ מִפְּנֵי פַּחְדָּם וְלֹא יוּכְלוּ לְהָמִית אוֹתָם בַּחֶרֶב מִפְּנֵי מִעוּטָם. וְר"א אָמַר (אבן עזרא על ויקרא כ"ו:ח') כִּי הַכֶּפֶל שֶׁיִּפְּלוּ פַּעַם אַחַר פַּעַם תָּמִיד בְּלִי תְּקוּמָה:
@7 וְטַעַם **וְהִפְרֵיתִי** שֶׁיַּעֲשׂוּ כֻּלָּם פֵּרוֹת פְּרִי הַבֶּטֶן, לֹא יִהְיֶה בָּהֶם עָקָר וַעֲקָרָה. וְחָזַר וְאָמַר "וְהִרְבֵּיתִי", שֶׁיַּעֲשׂוּ פֵּרוֹת רַבִּים וְלֹא יְשַׁכְּלוּ וִימַלְאוּ יְמֵיהֶם, וּלְכָךְ יִהְיוּ עַם רַב:
@9 **וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכְכֶם** זֶה בֵּית הַמִּקְדָּשׁ. **וְלֹא תִגְעַל נַפְשִׁי אֶתְכֶם** אֵין רוּחִי קָצָה בָכֶם. כָּל גְּעִילָה לְשׁוֹן פְּלִיטַת דָּבָר הַבָּלוּעַ בְּדָבָר, כְּגוֹן "כִּי שָׁם נִגְעַל מָגֵן גִּבּוֹרִים" (שמואל ב א כא), לֹא קִבֵּל הַמְּשִׁיחָה שֶׁמּוֹשְׁחִין מָגֵן שֶׁל עוֹר מְבֻשָּׁל כְּדֵי לְהַחְלִיק מֵעָלָיו מַכּוֹת חֵץ אוֹ חֲנִית שֶׁלֹּא יִקֹּב הָעוֹר, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ו:י"א). וְלֹא יָדַעְתִּי מָה הַטַּעַם בָּזֶה שֶׁיֹּאמַר הקב"ה כִּי בְּשָׁמְרֵנוּ כָּל הַמִּצְוֹת וַעֲשׂוֹתֵנוּ רְצוֹנוֹ לֹא יִמְאַס אוֹתָנוּ בְּגֹעַל נַפְשׁוֹ, וְכֵן בְּעָבְרֵנוּ עַל בְּרִיתוֹ וַעֲשׂוֹתֵנוּ נֶאָצוֹת גְּדוֹלוֹת אָמַר "לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים" (ויקרא כ"ו:מ"ד), וְאָמַר הַנָּבִיא בִּשְׁעַת הַקְּלָלָה "הֲמָאֹס מָאַסְתָּ אֶת יְהוּדָה אִם בְּצִיּוֹן גָּעֲלָה נַפְשֶׁךָ" (ירמיהו יד יט). אֲבָל הָעִנְיָן סוֹד מִסִּתְרֵי הַתּוֹרָה, אָמַר שֶׁיִּתֵּן מִשְׁכָּנוֹ בְּתוֹכֵנוּ, וְהַנֶּפֶשׁ אֲשֶׁר מִמֶּנָּה יָבֹא הַמִּשְׁכָּן לֹא תִּגְעַל אוֹתָנוּ, כִּכְלִי שֶׁמַּגְעִילִין אוֹתוֹ בְּרוֹתְחִין, אֲבָל בְּכָל עֵת יִהְיוּ בְּגָדֵינוּ לְבָנִים וַחֲדָשִׁים, כִּי הַגְּעִילָה - פְּלִיטָה, כְּדִבְרֵי רַשִׁ"י, מִלְּשׁוֹן "שׁוֹרוֹ עִבַּר וְלֹא יַגְעִל תְּפַלֵּט פָּרָתוֹ וְלֹא תְשַׁכֵּל" (איוב כא י). וְאָמַר "נַפְשִׁי" כְּדֶרֶךְ "נִשְׁבַּע ה' אֱלֹהִים בְּנַפְשׁוֹ" (עמוס ו ח), וְהַנָּבִיא אָמַר בִּתְמִיָּה, אִם בְּצִיּוֹן עַצְמָהּ גָּעֲלָה נַפְשֶׁךָ, שֶׁהִיא עִיר וָאֵם בְּיִשְׂרָאֵל, וְהִשְׁלַכְתָּ אוֹתָהּ מִלְּפָנֶיךָ לִהְיוֹת כָּל בָּנֶיהָ לְבוּשִׁים בְּגָדִים צוֹאִים נִגְאָלִים. וְהִנֵּה הַבְּרָכוֹת הָאֵלֶּה כְּפִי פְּשׁוּטָן עִם הֱיוֹתָן רַבּוֹת כְּלָלִיּוֹת בְּעִנְיַן הַמָּטָר הַשָּׂבָע וְהַשָּׁלוֹם וּפְרִיָּה וּרְבִיָּה, אֵינָן כְּמוֹ הַבְּרָכוֹת שֶׁבֵּרַךְ כְּבָר בִּקְצָרָה "וּבֵרַךְ אֶת לַחְמְךָ וְאֶת מֵימֶיךָ וַהֲסִרֹתִי מַחֲלָה מִקִּרְבֶּךָ" (שמות כג כה), כִּי שָׁם יַבְטִיחַ בְּמַאֲכָל וּבְמִשְׁתֶּה וְשֶׁיִּהְיֶה לִבְרָכָה, עַד שֶׁלֹּא יֶאֱרַע שׁוּם חֳלִי בְּגוּפֵינוּ וְעַל כֵּן יִהְיוּ כְּלֵי הַזֶּרַע שְׁלֵמִים וּבְרִיאִים, וְנוֹלִיד כַּהֹגֶן וְנִחְיֶה יָמִים מְלֵאִים, כְּמוֹ שֶׁאָמַר "לֹא תִהְיֶה מְשַׁכֵּלָה וַעֲקָרָה בְּאַרְצֶךָ אֶת מִסְפַּר יָמֶיךָ אֲמַלֵּא" (שם פסוק כו), וְכֵן אָמַר תְּחִלָּה "כִּי אֲנִי ה' רֹפְאֶךָ" (שם טו כו). וְהַטַּעַם בָּזֶה כִּי הַבְּרָכוֹת הָהֵם אע"פ שֶׁהֵם נִסִּים הֵם מִן הַנִּסִּים הַנִּסְתָּרִים שֶׁכָּל הַתּוֹרָה מְלֵאָה מֵהֶם כַּאֲשֶׁר פֵּרַשְׁתִּי (בראשית יז א), וְהֵם אֲפִלּוּ לְיָחִיד הָעוֹבֵד, כִּי כַּאֲשֶׁר יִהְיֶה הָאִישׁ הֶחָסִיד שׁוֹמֵר כָּל מִצְוֹת ה' אֱלֹהָיו, יִשְׁמְרֵהוּ הָאֵל מִן הַחֹלִי וְהָעֲקָרוּת וְהַשְּׁכוֹל וִימַלֵּא יָמָיו בְּטוֹבָה. אֲבָל אֵלּוּ הַבְּרָכוֹת שֶׁבַּפָּרָשָׁה הַזֹּאת הֵן כְּלָלִיּוֹת בָּעָם, וְהֵן בִּהְיוֹת כָּל עַמֵּנוּ כֻּלָּם צַדִּיקִים. וּלְכָךְ יַזְכִּיר תָּמִיד בְּכָאן "הָאָרֶץ", "וְנָתְנָה הָאָרֶץ פִּרְיָהּ" "וִישַׁבְתֶּם לָבֶטַח בְּאַרְצְכֶם" "וְנָתַתִּי שָׁלוֹם בָּאָרֶץ" "מִן הָאָרֶץ" "וְחֶרֶב לֹא תַעֲבֹר בְּאַרְצְכֶם". וּכְבָר בֵּאַרְנוּ כִּי כָּל אֵלֶּה הַבְּרָכוֹת כֻּלָּם נִסִּים, אֵין בַּטֶּבַע שֶׁיָּבֹאוּ הַגְּשָׁמִים וְיִהְיֶה הַשָּׁלוֹם לָנוּ מִן הָאוֹיְבִים וְיָבֹא מֹרֶךְ בְּלִבָּם לָנוּס מֵאָה מִפְּנֵי חֲמִשָּׁה בַּעֲשׂוֹתֵנוּ הַחֻקִּים וְהַמִּצְוֹת, וְלֹא שֶׁיִּהְיֶה הַכֹּל הֵפֶךְ מִפְּנֵי זָרְעֵנוּ הַשָּׁנָה הַשְּׁבִיעִית. וְאַף עַל פִּי שֶׁהֵם נִסִּים נִסְתָּרִים שֶׁעוֹלָם כְּמִנְהָגוֹ נוֹהֵג עִמָּהֶם, אֲבָל הֵם מִתְפַּרְסְמִים מִצַּד הֱיוֹתָם תָּמִיד לְעוֹלָם בְּכָל הָאָרֶץ, כִּי אִם הַצַּדִּיק הָאֶחָד יִחְיֶה וְיָסִיר ה' מַחֲלָה מִקִּרְבּוֹ וִימַלֵּא יָמָיו, יִקְרֶה גַּם זֶה בִּקְצָת רְשָׁעִים, אֲבָל שֶׁתִּהְיֶה אֶרֶץ אַחַת כֻּלָּהּ וְעַם אֶחָד תָּמִיד בְּרֶדֶת הַגֶּשֶׁם בְּעִתּוֹ וְשָׂבָע וְשַׁלְוָה וְשָׁלוֹם וּבְרִיאוּת וּגְבוּרָה וְשִׁבְרוֹן הָאוֹיְבִים, בְּעִנְיָן שֶׁאֵין כָּמוֹהוּ בְּכָל הָעוֹלָם, יִוָּדַע לַכֹּל כִּי מֵאֵת ה' הָיְתָה זֹּאת. וְעַל כֵּן אָמַר "וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךָ וְיָרְאוּ מִמֶּךָּ" (דברים כח י). וְהֵפֶךְ זֶה יִהְיֶה בַּקְּלָלוֹת בְּעָנְשֵׁי הָאָרֶץ, שֶׁאָמַר "וְנָתַתִּי אֶת שְׁמֵיכֶם כַּבַּרְזֶל" (ויקרא כ"ו:י"ט), וְעָנְשֵׁי הַחֹלִי, כְּמוֹ שֶׁאָמַר "וָחֳלָאִים רָעִים וְנֶאֱמָנִים" (דברים כח נט), שֶׁיְּקַלֵּל הַמַּאֲכָל וְיַחֲלִיא, וְיִתְפַּרְסֵם הַנֵּס בִּהְיוֹתוֹ תָּמִיד קַיָּם בְּכֻלָּם, עַל כֵּן כָּתוּב "וְאָמַר הַדּוֹר הָאַחֲרוֹן בְּנֵיכֶם אֲשֶׁר יָקוּמוּ מֵאַחֲרֵיכֶם וְהַנָּכְרִי אֲשֶׁר יָבֹא מֵאֶרֶץ רְחוֹקָה וְרָאוּ אֶת מַכּוֹת הָאָרֶץ הַהִיא וְאֶת תַּחֲלֻאֶיהָ" (שם כט כא), שֶׁלֹּא יִתְמְהוּ בָּאִישׁ הַהוּא אֲשֶׁר רָבְצָה בּוֹ כָּל הָאָלָה (שם פסוק יט), כִּי כֵן יִהְיֶה פְּעָמִים רַבִּים כְּמִנְהָגוֹ שֶׁל עוֹלָם בְּכָל הָאֻמּוֹת שֶׁיָּבֹאוּ מִקְרִים רָעִים בְּאִישׁ אֶחָד, רַק בָּאָרֶץ הַהִיא יִתְמְהוּ וְיִשְׁאֲלוּ כָּל הַגּוֹיִם "עַל מֶה עָשָׂה ה' כָּכָה לָאָרֶץ הַזֹּאת" (שם פסוק כג), כִּי כֻּלָּם יִרְאוּ וְיֵדְעוּ כִּי יַד ה' עָשְׂתָה זֹּאת, וְיֹאמְרוּ "עַל אֲשֶׁר עָזְבוּ אֶת בְּרִית ה' אֱלֹהֵי אֲבֹתָם" (שם פסוק כד). וְהַכְּלָל כִּי בִּהְיוֹת יִשְׂרָאֵל שְׁלֵמִים וְהֵם רַבִּים לֹא יִתְנַהֵג עִנְיָנָם בְּטֶבַע כְּלָל, לֹא בְּגוּפָם וְלֹא בְּאַרְצָם, לֹא בִּכְלָלָם וְלֹא בְּיָחִיד מֵהֶם, כִּי יְבָרֵךְ הַשֵּׁם לַחְמָם וּמֵימָם וְיָסִיר מַחֲלָה מִקִּרְבָּם עַד שֶׁלֹּא יִצְטָרְכוּ לְרוֹפֵא וּלְהִשְׁתַּמֵּר בְּדֶרֶךְ מִדַּרְכֵי הָרְפוּאוֹת כְּלָל, כְּמוֹ שֶׁאָמַר "כִּי אֲנִי ה' רֹפְאֶךָ" (שמות טו כו). וְכֵן הָיוּ הַצַּדִּיקִים עוֹשִׂים בִּזְמַן הַנְּבוּאָה, גַּם כִּי יִקְרֵם עָוֹן שֶׁיֶּחֱלוּ לֹא יִדְרְשׁוּ בָּרֹפְאִים רַק בַּנְּבִיאִים, כְּעִנְיַן חִזְקִיָּהוּ בַּחֲלוֹתוֹ (מ"ב כ ב ג). וְאָמַר הַכָּתוּב "גַּם בְּחָלְיוֹ לֹא דָרַשׁ אֶת ה' כִּי בָּרֹפְאִים" (דהי"ב טז יב), וְאִלּוּ הָיָה דְּבַר הָרוֹפְאִים נָהוּג בָּהֶם מָה טַעַם שֶׁיַּזְכִּיר הָרוֹפְאִים, אֵין הָאָשָׁם רַק בַּעֲבוּר שֶׁלֹּא דָּרַשׁ הַשֵּׁם, אֲבָל הוּא כַּאֲשֶׁר יֹאמַר אָדָם לֹא אָכַל פְּלוֹנִי מַצָּה בְּחַג הַמַּצּוֹת כִּי אִם חָמֵץ. אֲבָל הַדּוֹרֵשׁ הַשֵּׁם בַּנָּבִיא לֹא יִדְרֹשׁ בָּרֹפְאִים, וּמַה חֵלֶק לָרוֹפְאִים בְּבֵית עוֹשֵׂי רְצוֹן הַשֵּׁם אַחַר שֶׁהִבְטִיחַ "וּבֵרַךְ אֶת לַחְמְךָ וְאֶת מֵימֶיךָ וַהֲסִרֹתִי מַחֲלָה מִקִּרְבֶּךָ" (שמות כג כה), וְהָרוֹפְאִים אֵין מַעֲשֵׂיהֶם רַק עַל הַמַּאֲכָל וְהַמַּשְׁקֶה, לְהַזְהִיר מִמֶּנּוּ וּלְצַוּוֹת עָלָיו, וְכָךְ אָמְרוּ (ברכות סד), כָּל עֶשְׂרִין וְתַרְתֵּין שְׁנִין דִּמְלַךְ רַבָּה, רַב יוֹסֵף אֲפִלּוּ אֻמָּנָא לְבֵיתֵהּ לָא קְרָא. וְהַמָּשָׁל לָהֶם (במדב"ר ט יג), תַּרְעָא דְּלָא פְּתִיחַ לְמִצְוָתָא פְּתִיחַ לְאַסְיָא. וְהוּא מַאֲמָרָם (ברכות ס), שֶׁאֵין דַּרְכָּם שֶׁל בְּנֵי אָדָם בָּרְפוּאוֹת אֶלָּא שֶׁנָּהֲגוּ; שֶׁאִלּוּ לֹא הָיָה דַּרְכָּם בִּרְפוּאוֹת, יֶחֱלֶה הָאָדָם כְּפִי אֲשֶׁר יִהְיֶה עָלָיו עֹנֶשׁ חֶטְאוֹ וְיִתְרַפֵּא בִּרְצוֹן ה', אֲבָל הֵם נָהֲגוּ בָּרְפוּאוֹת וְהַשֵּׁם הִנִּיחָם לְמִקְרֵי הַטְּבָעִים. וְזוֹ הִיא כַּוָּנָתָם בְּאָמְרָם (שם), "וְרַפֹּא יְרַפֵּא", מִכָּאן שֶׁנִּתְּנָה רְשׁוּת לָרוֹפֵא לְרַפּאוֹת; לֹא אָמְרוּ שֶׁנִּתְּנָה רְשׁוּת לַחוֹלֶה לְהִתְרַפְּאוֹת אֶלָּא כֵּיוָן שֶׁחָלָה הַחוֹלֶה וּבָא לְהִתְרַפְּאוֹת, כִּי נָהַג בָּרְפוּאוֹת וְהוּא לֹא הָיָה מֵעֲדַת הַשֵּׁם שֶׁחֶלְקָם בַּחַיִּים, אֵין לָרוֹפֵא לֶאֱסֹר עַצְמוֹ מֵרְפוּאָתוֹ, לֹא מִפְּנֵי חֲשָׁשׁ שֶׁמָּא יָמוּת בְּיָדוֹ אַחֲרֵי שֶׁהוּא בָּקִי בַּמְּלָאכָה הַהִיא, וְלֹא בַּעֲבוּר שֶׁיֹּאמַר כִּי הַשֵּׁם לְבַדּוֹ הוּא רוֹפֵא כָל בָּשָׂר, שֶׁכְּבָר נָהֲגוּ. וְעַל כֵּן הָאֲנָשִׁים הַנִּצִּים שֶׁהִכּוּ זֶה אֶת זֶה בְּאֶבֶן אוֹ בְּאֶגְרוֹף (שמות כא יח), יֵשׁ עַל הַמַּכֶּה תַּשְׁלוּמֵי הָרְפוּאָה, כִּי הַתּוֹרָה לֹא תִּסְמֹךְ בְּדִינֶיהָ עַל הַנִּסִּים, כַּאֲשֶׁר אָמְרָה "כִּי לֹא יֶחְדַּל אֶבְיוֹן מִקֶּרֶב הָאָרֶץ" (דברים טו יא), מִדַּעְתּוֹ שֶׁכֵּן יִהְיֶה. אֲבָל בִּרְצוֹת הַשֵּׁם דַּרְכֵי אִישׁ אֵין לוֹ עֵסֶק בָּרֹפְאִים:
@10 וְטַעַם **וְהִתְהַלַּכְתִּי בְּתוֹכְכֶם** שֶׁתִּהְיֶה הַנְהָגָתִי בָּכֶם מְפֻרְסֶמֶת כְּמֶלֶךְ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנֵהוּ, מַסְפִּיק לָהֶם כָּל צָרְכָּם. וְזֶה דֶּרֶךְ דִּבְרֵי הַבְּרִית כִּפְשׁוּטָן, וְהוּא אֱמֶת, וְכָךְ יַעֲשֶׂה בָּהֶן בְּוַדַּאי. וְלֹא הִזְכִּיר הַכָּתוּב בְּכָאן שְׂכַר קִיּוּם הַנְּפָשׁוֹת בְּעוֹלַם הַנְּשָׁמוֹת וּבָעוֹלָם הַבָּא אַחֲרֵי תְּחִיַּת הַמֵּתִים, כִּי קִיּוּמָן מְחֻיָּב בְּדֶרֶךְ הַיְּצִירָה כְּמוֹ שֶׁפֵּרַשְׁתִּי בַּכְּרֵתוֹת (רמב"ן על ויקרא י"ח:כ"ט), וְהָעֹנֶשׁ הוּא שֶׁמַּכְרִית הַחַיָּבִים מֵהֶם, וְהַשְּׁאָר כֻּלָּם יִתְקַיְּמוּ בְּדֶרֶךְ יְצִירָתָם. אֲבָל עַל דֶּרֶךְ הָאֱמֶת, הַבְּרָכוֹת הָאֵלֶּה עוֹד הֵם בִּרְכוֹת שָׁמַיִם בָּעֶלְיוֹנִים כְּמוֹ שֶׁפֵּרַשְׁתִּי, "וְנָתַתִּי שָׁלוֹם בָּאָרֶץ", "וְלֹא תִגְעַל נַפְשִׁי אֶתְכֶם" וְכֵן "וְהִתְהַלַּכְתִּי בְּתוֹכְכֶם", רֶמֶז לְמִדָּה שֶׁקָּרְאוּ רַבּוֹתֵינוּ "שְׁכִינָה", מִן "וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכְכֶם", וְאוֹמְרִים (מנחות פו), שְׁכִינָה שׁוֹרָה בְּיִשְׂרָאֵל, וְאָמְרוּ (בראשית רבה י"ט:ז'), עִקַּר שְׁכִינָה בַּתַּחְתּוֹנִים הָיְתָה. וְהִנֵּה הֻזְכַּר כָּאן גַּן עֵדֶן וְהָעוֹלָם הַבָּא לְיוֹדְעָיו. וְאֵלֶּה הַבְּרָכוֹת בְּתַשְׁלוּמֵיהֶן לֹא תִּהְיֶינָה רַק בִּהְיוֹת כָּל יִשְׂרָאֵל עוֹשִׂין רְצוֹן אֲבִיהֶם, וּבִנְיַן שָׁמַיִם וָאָרֶץ שָׁלֵם עַל מְכוּנָתוֹ, וְאֵין בַּתּוֹרָה בְּרָכוֹת שְׁלֵמוֹת כָּאֵלֶּה, שֶׁהֵם דִּבְרֵי הַבְּרִית וְהַתְּנָאִים אֲשֶׁר בֵּין הקב"ה וּבֵינֵינוּ. וְדַע כִּי לֹא הִשִּׂיגוּ יִשְׂרָאֵל מֵעוֹלָם לַבְּרָכוֹת הָאֵלֶּה בִּשְׁלֵמוּתָן, לֹא הָרַבִּים וְלֹא הַיְּחִידִים מֵהֶם, שֶׁלֹּא עָלְתָה זְכוּתָם לְכָךְ, כְּמוֹ שֶׁאָמְרוּ (מו"ק טז) עַל דָּוִד, (והוא עורר את חניתו) עַל שְׁמֹנֶה מֵאוֹת חָלָל, וְהָיָה מִצְטַעֵר עַל מָאתַיִם, יָצְתָה בַּת קוֹל וְאָמְרָה לוֹ, רַק בִּדְבַר אוּרִיָּה הַחִתִּי (מלכים טו ה). וְעַל כֵּן תִּמְצָא לְרַבּוֹתֵינוּ זַ"ל שֶׁיַּזְכִּירוּ בַּפְּסוּקִים הָאֵלֶּה לֶעָתִיד לָבוֹא, מְלַמֵּד שֶׁתִּינוֹק מִיִּשְׂרָאֵל עָתִיד לִהְיוֹת מוֹשִׁיט וְכוּ' (תו"כ פרק ב ב), עָתִיד הקב"ה לְטַיֵּל עִם הַצַּדִּיקִים לֶעָתִיד לָבוֹא (שם פרק ג ג); כִּי לֹא נִתְקַיֵּם, אֲבָל יִתְקַיֵּם עִמָּנוּ בִּזְמַן הַשְּׁלֵמוּת:
@13 **וְאִם בְּחֻקֹּתַי תִּמְאָסוּ** בַּעֲבוּר הֱיוֹת הַחֻקִּים מִצְוֹת לֹא נִתְגַּלָּה טַעְמָם לֶהָמוֹן, יִמְאֲסוּ אוֹתָם הַכְּסִילִים, יֹאמְרוּ מַה הַחֵפֶץ לַשֵּׁם שֶׁלֹּא אֶלְבַּשׁ הַבֶּגֶד הַזֶּה הַמְרֻקָּם בְּרִקְמֵי שֵׁשׁ וּתְכֵלֶת, וּמָה נוֹעִיל כִּי נִשְׂרֹף הַפָּרָה וְנִזְרֹק עָלֵינוּ הָאֵפֶר. אֲבָל הַמִּשְׁפָּטִים הַכֹּל חֲפֵצִים בָּהֶם וְהַכֹּל צְרִיכִים אוֹתָם, אֵין יִשּׁוּב לְעַם וּמְדִינָה בִּלְתִּי מִשְׁפָּט, וְלֹא תִּגְעַל נֶפֶשׁ שׁוּם אָדָם מִשְׁפַּט "מַכֵּה אִישׁ וָמֵת" (שמות כא יב), "וְכִי יִנָּצוּ" (שם פסוק כב), וְדִינֵי הַשּׁוֹר וְהַבּוֹר וְהַשּׁוֹמְרִים וְכַיּוֹצֵא בָּהֶם. אֲבָל הַמִּשְׁפָּט אֲשֶׁר נַעֲשֶׂה בְּעוֹבְרֵי הַמִּצְוֹת, כְּאִישׁ אֲשֶׁר יִבְעֹל הָעֲרָיוֹת אוֹ יְחַלֵּל הַשַּׁבָּת וְיַעֲשֶׂה אוֹב וְיִדְּעוֹנִי, בָּזֶה יָקוּצוּ, מִפְּנֵי הַמִּצְוֹת שֶׁהֵן עוֹל כָּבֵד עַל הָרְשָׁעִים, וּלְכָךְ אָמַר, "וְאִם אֶת מִשְׁפָּטַי תִּגְעַל נַפְשְׁכֶם לְבִלְתִּי עֲשׂוֹת אֶת כָּל מִצְוֹתַי", כִּי הַגְּעִילָה בַּמִּשְׁפָּטִים כְּדֵי שֶׁלֹּא יַעֲשׂוּ הַמִּצְוֹת:
@13 וְטַעַם **לְהַפְרְכֶם אֶת בְּרִיתִי** שֶׁתּוּפַר הַבְּרִית לְגַמְרֵי וְיִהְיוּ בְּלֹא תּוֹרָה, לְהַתִּיר לְעַצְמָם עֲרָיוֹת בְּפַרְהֶסְיָא וְכָל תַּאֲוָה תֶּעֱרַב לְנַפְשָׁם. וְעַל דֶּרֶךְ הָאֱמֶת שֶׁתּוּפַר זֹאת הַבְּרִית וְתִבְטַל, הֵפֶךְ "וְנָתַתִּי שָׁלוֹם בָּאָרֶץ" (ויקרא כ"ו:ו'), וְהוּא מַה שֶׁאָמַר "אֲשֶׁר הֵמָּה הֵפֵרוּ אֶת בְּרִיתִי וְאָנֹכִי בָּעַלְתִּי בָם" (ירמיהו לא לא), כִּי בַּעֲבוּר שֶׁבִּטְּלוּ אֶת בְּרִיתִי שָׁלוֹם, בָּעַלְתִּי בָּם בְּעַצְמָם:
@14 וְטַעַם **אַף אֲנִי אֶעֱשֶׂה זֹּאת לָכֶם** עַל דֶּרֶךְ הָאֱמֶת כְּמוֹ בְּהִפּוּךְ, אַף אֲנִי זֹאת אֶעֱשֶׂה לָכֶם. וְזֶהוּ שֶׁמַּזְכִּיר תָּמִיד בַּפָּרָשָׁה "אֲנִי", "וְהָלַכְתִּי אַף אֲנִי" (ויקרא כ"ו:כ"ד), "וְהִכֵּיתִי אֶתְכֶם גַּם אָנִי" (שם), "וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי" (ויקרא כ"ו:כ"ח), "וַהֲשִׁמּוֹתִי אֲנִי" (ויקרא כ"ו:ל"ב), "אַף אֲנִי אֵלֵךְ עִמָּם" (ויקרא כ"ו:מ"א). וּבְמִדְרָשׁוֹ שֶׁל רַבִּי נְחוּנְיָא בֶּן הַקָּנָה, לֹא דַּי שֶׁאֲנִי אָדוּן הַדִּין אֶלָּא אַף אֲנִי אֲיַסֵּר וְכוּ'. וְהַכְּלָל כִּי הקב"ה כּוֹרֵת הַבְּרִית הַזֹּאת, וְזֶה טַעַם "שֶׁבַע עַל חַטֹּאתֵיכֶם", "שֶׁבַע כְּחַטֹּאתֵיכֶם", וְהָאָלוֹת הֵן אָלוֹת הַבְּרִית, כִּי הַדִּבּוּר מִפִּי הַגְּבוּרָה וּבִלְשׁוֹן עַצְמוֹ, "אֶעֱשֶׂה", "יִסַּרְתִּי" "וְהִכֵּתִי", וּלְכָךְ אָמַר "אֲשֶׁר נָתַן ה' בֵּינוֹ וּבֵין בְּנֵי יִשְׂרָאֵל" (ויקרא כ"ו:מ"ו), כִּי הוּא בִּשְׁמוֹ הַגָּדוֹל נָתַן הַבְּרִית הַזֹּאת. אֲבָל בְּמִשְׁנֵה תּוֹרָה (דברים כח טו) אָמַר "אִם לֹא תִשְׁמַע בְּקוֹל ה' אֱלֹהֶיךָ לִשְׁמֹר לַעֲשׂוֹת אֶת כָּל מִצְוֹתָיו", וְיַזְכִּיר שָׁם תָּמִיד לְשׁוֹן אֲרִירָה, וּפָתַח בָּהֶן "אָרוּר אַתָּה" (שם פסוק טז), כִּי הַבְּרָכָה נֶעְדֶּרֶת מֵהֶם, וְאָמַר "יִתֵּן ה'" (שם פסוק כד). וְזֶהוּ מַאֲמַר רַבּוֹתֵינוּ (מגילה לא), קְלָלוֹת שֶׁבְּת"כ בִּלְשׁוֹן רַבִּים, וּמֹשֶׁה כִּי אֲמָרָן מִפִּי הַגְּבוּרָה אֲמָרָן, וְשֶׁבְּמִשְׁנֵה תּוֹרָה בִּלְשׁוֹן יָחִיד, וּמֹשֶׁה כִּי אֲמָרָן מִפִּי עַצְמוֹ אֲמָרָן; כִּי הַגְּבוּרָה עָשְׂתָה מֹשֶׁה שָׁלִיחַ בֵּינָהּ וּבֵין כָּל יִשְׂרָאֵל. וְדַע וְהָבֵן כִּי הָאָלוֹת הָאֵלֶּה יִרְמְזוּ לְגָלוּת רִאשׁוֹן, כִּי בַּבַּיִת הָרִאשׁוֹן הָיוּ כָּל דִּבְרֵי הַבְּרִית הַזֹּאת, הַגָּלוּת וְהַגְּאֻלָּה מִמֶּנּוּ, שֶׁכֵּן תִּרְאֶה בַּתּוֹכָחוֹת שֶׁאָמַר (ויקרא כ"ו:ט"ו), "וְאִם בְּחֻקֹּתַי תִּמְאָסוּ וְאִם אֶת מִשְׁפָּטַי תִּגְעַל נַפְשְׁכֶם", וְאָמַר "לְהַפְרְכֶם אֶת בְּרִיתִי" (שם), וְהִזְכִּיר בָּהֶם בָּמוֹת וְחַמָּנִים וְגִלּוּלִים (ויקרא כ"ו:ל'), כִּי הָיוּ עוֹבְדֵי עֲבוֹדָה זָרָה וְעוֹשִׂים כָּל הָרָעוֹת, וְהוּא שֶׁאָמַר "וַהֲשִׁמּוֹתִי אֶת מִקְדְּשֵׁיכֶם וְלֹא אָרִיחַ בְּרֵיחַ נִיחֹחֲכֶם" (ויקרא כ"ו:ל"א), יַתְרֶה בָּהֶם לְסַלֵּק מֵהֶם מִקְדָּשׁוֹ וְקִבּוּל הַקָּרְבָּנוֹת שֶׁהָיוּ לְרָצוֹן לוֹ בַּמִּקְדָּשׁ הַהוּא, וְהָעֳנָשִׁים עֲלֵיהֶם חֶרֶב וְחַיָּה רָעָה וְדֶבֶר וְרָעָב וְגָלוּת בַּסּוֹף - כִּי כָל זֶה הָיָה שָׁם כַּאֲשֶׁר בָּא בְּפֵרוּשׁ בְּסֵפֶר יִרְמְיָהוּ (לב כד). וְאָמַר בַּגָּלוּת "אָז תִּרְצֶה הָאָרֶץ אֶת שַׁבְּתֹתֶיהָ וְגוֹ' כָּל יְמֵי הָשַּׁמָּה תִּשְׁבֹּת אֵת אֲשֶׁר לֹא שָׁבְתָה" (ויקרא כ"ו:ל"ד-ל"ה), שֶׁהָיוּ שְׁנוֹת הַגָּלוּת כַּשָּׁנִים אֲשֶׁר בִּטְּלוּ הַשְּׁמִטּוֹת. וְכֵן אָמַר הַכָּתוּב בַּגָּלוּת הַהוּא, "לְמַלֹּאת דְּבַר ה' בְּפִי יִרְמְיָהוּ עַד רָצְתָה הָאָרֶץ אֶת שַׁבְּתוֹתֶיהָ כָּל יְמֵי הָשַּׁמָּה שָׁבָתָה לְמַלֹּאת שִׁבְעִים שָׁנָה" (דהי"ב לו כא), כֵּן הִתְרָה בָּהֶם וְכֵן הִגִּיעַ אֲלֵיהֶם. א"כ דָּבָר בָּרוּר הוּא שֶׁעַל הַגָּלוּת הַהוּא דִּבֵּר הַכָּתוּב. וְהִסְתַּכֵּל עוֹד בְּעִנְיַן הַגְּאֻלָּה מִמֶּנּוּ, שֶׁאֵינוֹ מַבְטִיחַ רַק שֶׁיִּזְכֹּר בְּרִית אָבוֹת וּבִזְכִירַת הָאָרֶץ (ויקרא כ"ו:מ"ב), לֹא שֶׁיִּמְחֹל עֲוֹנָם וְיִסְלַח חַטָּאתָם וְיוֹסִיף אַהֲבָתָם כְּקֶדֶם, וְלֹא שֶׁיֶּאֱסֹף אֶת נִדְחֵיהֶם, כִּי הָיָה כֵן בַּעֲלוֹתָם מִבָּבֶל, שֶׁלֹּא שָׁבוּ רַק יְהוּדָה וּבִנְיָמִין וְהַנִּלְוִים עִמָּהֶם מְעַט מִקְּצָת הַשְּׁבָטִים אֲשֶׁר גָּלוּ לְבָבֶל, וְשָׁבוּ בְּדַלּוּת בְּעַבְדוּת מַלְכֵי פָּרַס. וְגַם לֹא אָמַר שֶׁיָּשׁוּבוּ בִּתְשׁוּבָה שְׁלֵמָה לְפָנָיו, רַק שֶׁיִּתְוַדּוּ עֲוֹנָם וַעֲוֹן אֲבוֹתָם (ויקרא כ"ו:מ'), וּמָצִינוּ אַנְשֵׁי בַּיִת שֵׁנִי עוֹשִׂים כֵּן, כְּמוֹ שֶׁהִתְוַדָּה דָּנִיֵּאל "חָטָאנוּ וְעָוִינוּ וְהִרְשַׁעְנוּ וּמָרָדְנוּ וְסוֹר מִמִּצְוֹתֶיךָ וְגוֹ' לְמַלְכֵּנוּ לְשָׂרֵינוּ וְלַאֲבוֹתֵינוּ" (דניאל ט ה ח), וּכְתִיב "כִּי בַחֲטָאֵינוּ וּבַעֲוֹנוֹת אֲבֹתֵינוּ יְרוּשָׁלִַם וְעַמְּךָ לְחֶרְפָּה" (שם שם טז), וְכֵן נְחֶמְיָה הִתְוַדָּה (נחמיה א ה-יא), וְעֶזְרָא אָמַר "מְלָכֵינוּ שָׂרֵינוּ כֹּהֲנֵינוּ וַאֲבֹתֵינוּ לֹא עָשׂוּ תּוֹרָתֶךָ" (שם ט לד), הֲרֵי כִּי כֻּלָּם לָמְדוּ מִן הַתּוֹרָה שֶׁיִּתְוַדּוּ עֲוֹנָם וַעֲוֹן אֲבוֹתָם. וְכָל אֵלֶּה דְּבָרִים בְּרוּרִים בַּבְּרִית הַזֹּאת, שֶׁהוּא בֶּאֱמֶת יִרְמֹז לַגָּלוּת הָרִאשׁוֹן וְהַגְּאוּלָּה מִמֶּנּוּ. אֲבָל הַבְּרִית שֶׁבְּמִשְׁנֵה תּוֹרָה יִרְמֹז לְגָלוּתֵנוּ זֶה וְלַגְּאֻלָּה שֶׁנִּגָּאֵל מִמֶּנּוּ, כִּי הִסְתַּכַּלְנוּ תְּחִלָּה שֶׁלֹּא נִרְמַז שָׁם קֵץ וְקֶצֶב, וְלֹא הִבְטִיחַ בַּגְּאֻלָּה רַק תָּלָה אוֹתָהּ בִּתְשׁוּבָה, וְלֹא הִזְכִּיר בַּעֲבֵרוֹת הָהֵם שֶׁיַּעֲשׂוּ אֲשֵׁרִים וְחַמָּנִים וְשֶׁיַּעַבְדוּ עֲבוֹדָה זָרָה כְּלָל, אֲבָל אָמַר "וְהָיָה אִם לֹא תִשְׁמַע בְּקוֹל ה' אֱלֹהֶיךָ לִשְׁמֹר לַעֲשׂוֹת אֶת כָּל מִצְוֹתָיו וְחֻקֹּתָיו" (דברים כח טו), אָמַר כִּי מִפְּנֵי שֶׁיַּעַבְרוּ עַל קְצָת מִצְוֹתָיו שֶׁלֹּא יִשְׁמְרוּ וְיַעֲשׂוּ אֶת כֻּלָּן - יֵעָנְשׁוּ, שֶׁכָּךְ הָיָה בְּבַיִת שֵׁנִי, כְּמוֹ שֶׁאָמְרוּ (יומא ט) שֶׁבַּיִת רִאשׁוֹן מִפְּנֵי מָה חָרַב, מִפְּנֵי עֲבוֹדָה זָרָה וְגִלּוּי עֲרָיוֹת וּשְׁפִיכוּת דָּמִים; בַּיִת שֵׁנִי שֶׁאָנוּ בְּקִיאִים בָּהֶם שֶׁהָיוּ עוֹסְקִין בַּתּוֹרָה וּבִגְמִילוּת חֲסָדִים, מִפְּנֵי מָה חָרַב, מִפְּנֵי שִׂנְאַת חִנָּם שֶׁהָיְתָה בֵּינֵיהֶם. וְלֹא הִזְכִּיר שָׁם הַמִּקְדָּשׁ וְרֵיחַ נִיחוֹחַ כַּאֲשֶׁר הִזְכִּיר כָּאן, שֶׁלֹּא הָיְתָה הָאֵשׁ יוֹרֶדֶת וְאוֹכֶלֶת הַקָּרְבָּנוֹת בְּבַיִת שֵׁנִי, כְּמוֹ שֶׁהֵעִידוּ בְּמַסֶּכֶת יוֹמָא שָׁם (כא). וְאָמַר בַּקְּלָלוֹת "יִשָּׂא ה' עָלֶיךָ גּוֹי מֵרָחוֹק מִקְצֵה הָאָרֶץ כַּאֲשֶׁר יִדְאֶה הַנָּשֶׁר" (דברים כח מט), שֶׁבָּאוּ עֲלֵיהֶם עַם רוֹמִי הָרְחוֹקִים מֵהֶם מְאֹד. וְאָמַר שָׁם "אֶל גּוֹי אֲשֶׁר לֹא יָדַעְתָּ" (שם פסוק לו), "גּוֹי אֲשֶׁר לֹא תִשְׁמַע לְשֹׁנוֹ" (שם פסוק מט), מִפְּנֵי רֹב רִחוּקָם מֵאַרְצֵנוּ, וְלֹא כֵן בְּדִבְרֵי הַבְּרִית הַזֹּאת, כִּי גָּלוּ לְבָבֶל וְאַשּׁוּר שֶׁהֵם קְרוֹבִים לָאָרֶץ וְנִלְחָמִים בָּהֶם תָּמִיד, וְיִחוּס יִשְׂרָאֵל מִשָּׁם הָיָה, וְיוֹדְעִים לְשׁוֹנָם, כְּעִנְיָן שֶׁנֶּאֱמַר "דַּבֶּר נָא אֶל עֲבָדֶיךָ אֲרָמִית כִּי שֹׁמְעִים אֲנָחְנוּ" (מלכים ב יח כו). וְכֵן "וֶהֱפִיצְךָ ה' בְּכָל הָעַמִּים מִקְצֵה הָאָרֶץ וְעַד קְצֵה הָאָרֶץ" (דברים כח סד) הוּא גָּלוּתֵנוּ הַיּוֹם, שֶׁאָנוּ מְפֻזָּרִים מִסּוֹף הָעוֹלָם וְעַד סוֹפוֹ. וְאָמַר "וֶהֱשִׁיבְךָ ה' מִצְרַיִם בָּאֳנִיּוֹת" (שם פסוק סח), וּבְגָלוּתֵנוּ זֶה הָיָה שֶׁמִּלֵּא טִיטוּס מֵהֶם סְפִינוֹת, וְכֵן כָּתוּב בְּסֵפֶר הָרוֹמִיִּים. וְכֵן מַה שֶׁאוֹמֵר שָׁם "בָּנֶיךָ וּבְנֹתֶיךָ נְתֻנִים לְעַם אַחֵר וְעֵינֶיךָ רוֹאוֹת" (דברים כ"ח:ל"ב), "בָּנִים וּבָנוֹת תּוֹלִיד וְלֹא יִהְיוּ לָךְ כִּי יֵלְכוּ בַּשֶּׁבִי" (שם פסוק מא), אֵינֶנּוּ הַגָּלוּת שֶׁגָּלוּ אָבוֹת וּבָנִים, רַק הַשֶּׁבִי הַהוּא לַבָּנִים לְבַדָּם וְהָאָבוֹת נִשְׁאָרִים בָּאָרֶץ, וְלֹא נֶאֱמַר כֵּן בַּבְּרִית הָרִאשׁוֹן מִפְּנֵי שֶׁגָּלוּ גָּלוּת שְׁלֵמָה, אֲבָל בַּבְּרִית הַשֵּׁנִי הִזְכִּיר כֵּן, שֶׁהָיוּ הָרוֹמִיִּים מוֹשְׁלִים בְּאַרְצֵנוּ וְלוֹקְחִים הַבָּנִים וְהַבָּנוֹת כִּרְצוֹנָם. וְכֵן "וְעָבַדְתָּ אֶת אֹיְבֶיךָ אֲשֶׁר יְשַׁלְּחֶנּוּ ה' בָּךְ בְּרָעָב וּבְצָמָא" (שם פסוק מח), הִיא עַבְדוּתֵנוּ שֶׁעָבַדְנוּ הָרוֹמִיִּים בְּאַרְצֵנוּ, וְשָׂרֵיהֶם מוֹשְׁלִים בָּאָרֶץ וּמַכְבִּידִים עָלֵינוּ עוֹל כָּבֵד, וְלוֹקְחִים גּוּפֵינוּ וּמָמוֹנֵנוּ, כַּאֲשֶׁר הוּא יָדוּעַ בַּסְּפָרִים. וְעוֹד רְאָיָה שֶׁאָמַר "יוֹלֵךְ ה' אֹתְךָ וְאֶת מַלְכְּךָ אֲשֶׁר תָּקִים עָלֶיךָ אֶל גּוֹי אֲשֶׁר לֹא יָדַעְתָּ אַתָּה וַאֲבֹתֶיךָ" (שם פסוק לו), כִּי הָלַךְ אַגְרִיפַּס הַמֶּלֶךְ בְּסוֹף בַּיִת שֵׁנִי לְרוֹמִי, וְעַל הֲלִיכָתוֹ שָׁם נֶחְרַב הַבַּיִת. וְלֹא אָמַר הַכָּתוּב "הַמֶּלֶךְ אֲשֶׁר יִמְלֹךְ עָלֶיךָ", אֲבָל אָמַר "מַלְכְּךָ אֲשֶׁר תָּקִים", רָמַז לָנוּ יִתְבָּרַךְ שֶׁלֹּא הָיָה רָאוּי לִמְלֹךְ, וְאָסוּר הָיָה לִהְיוֹת מֶלֶךְ עַל יִשְׂרָאֵל מִדִּין תּוֹרָה, אֲבָל הֵקִימוּ עֲלֵיהֶם הוּא וַאֲבוֹתָיו שֶׁלֹּא כַּדָּת, כְּמוֹ שֶׁהֻזְכַּר זֶה בְּמַסֶּכֶת סוֹטָה (סוטה מ"א). וְכָל אֵלֶּה רְמָזִים כָּאֵלּוּ יַזְכִּירוּ בְּפֵרוּשׁ עִנְיַן גָּלוּתֵנוּ זֶה. וְהַגְּאֻלָּה בַּבְּרִית הַהִיא הַשֵּׁנִית גְּאֻלָּה שְׁלֵמָה מְעֻלָּה עַל כֻּלָּם. אָמַר, "וְהָיָה כִי יָבֹאוּ עָלֶיךָ כָּל הַדְּבָרִים הָאֵלֶּה הַבְּרָכָה וְהַקְּלָלָה" וְגוֹ' (דברים ל א), וְהִבְטִיחַ "וֶהֱטִיבְךָ וְהִרְבְּךָ מֵאֲבוֹתֶיךָ" (שם פסוק ה), שֶׁהִיא הַבְטָחָה לְכָל שִׁבְטֵי יִשְׂרָאֵל, לֹא לְשִׁשִּׁית הָעָם. וְשָׁם הִבְטִיחַ שֶׁיַּכְרִית וִיכַלֶּה הַמַּגְלִים אוֹתָנוּ, שֶׁנֶּאֱמַר "וְנָתַן ה' אֱלֹהֶיךָ אֵת כָּל הָאָלוֹת הָאֵלֶּה עַל אֹיְבֶיךָ וְעַל שֹׂנְאֶיךָ אֲשֶׁר רְדָפוּךָ" (שם פסוק ז), וְהִנֵּה אוֹיְבֶיךָ וְשׂוֹנְאֶיךָ רֶמֶז לִשְׁתֵּי הָאֻמּוֹת אֲשֶׁר יִרְדְּפוּ תָּמִיד אַחֲרֵינוּ. וְאֵלֶּה דְּבָרִים יַבְטִיחוּ בַּגְּאֻלָּה הָעֲתִידָה הַבְטָחָה שְׁלֵמָה יוֹתֵר מִכָּל חֶזְיוֹנוֹת דָּנִיֵּאל. וְכֵן מַה שֶׁאָמַר בְּכָאן "וְשָׁמְמוּ עָלֶיהָ אוֹיְבֵיכֶם" (ויקרא כ"ו:ל"ב) הִיא בְּשׂוֹרָה טוֹבָה מְבַשֶּׂרֶת בְּכָל הַגָּלֻיּוֹת, שֶׁאֵין אַרְצֵנוּ מְקַבֶּלֶת אֶת אוֹיְבֵינוּ. וְגַם זוֹ רְאָיָה גְּדוֹלָה וְהַבְטָחָה לָנוּ, כִּי לֹא תִּמָּצֵא בְּכָל הַיִּשּׁוּב אֶרֶץ אֲשֶׁר הִיא טוֹבָה וּרְחָבָה וַאֲשֶׁר הָיְתָה נוֹשֶׁבֶת מֵעוֹלָם - וְהִיא חֲרֵבָה כָּמוֹהָ, כִּי מֵאָז יָצָאנוּ מִמֶּנָּה לֹא קִבְּלָה אֻמָּה וְלָשׁוֹן, וְכֻלָּם מִשְׁתַּדְּלִים לְהוֹשִׁיבָהּ וְאֵין לְאֵל יָדָם. וְהִנֵּה הַבְּרִית הָרִאשׁוֹנָה אֲשֶׁר בַּפָּרָשָׁה הַזֹּאת הקב"ה כָּרַת אוֹתָהּ, כִּי כֵן הָיָה שְׁמוֹ הַגָּדוֹל עִמָּנוּ בַּבַּיִת הָרִאשׁוֹן, וְהַבְּרִית הַשֵּׁנִית אֲשֶׁר בְּפָרָשַׁת וְהָיָה כִּי תָבֹא מִפִּי מֹשֶׁה, רֶמֶז לְסִלּוּק שְׁכִינָתוֹ לְגַמְרֵי, שֶׁלֹּא הָיָה בְּבַיִת שֵׁנִי רַק כְּבוֹד שְׁמוֹ, שֶׁנֶּאֱמַר "וְאֶרְצֶה בּוֹ וְאֶכָּבְדָה" (חגי א ח), וְתוֹסֶפֶת הַהֵ"א רֶמֶז לְהֵ"א שְׁנִיָּה שֶׁבַּשֵּׁם הַגָּדוֹל, וּכְבָר דָּרְשׁוּ בּוֹ (יומא כא) מִדְרָשׁ אַחֵר גַּם כֵּן, רֶמֶז לַחֲמִשָּׁה דְּבָרִים שֶׁהָיָה הַבַּיִת הַשֵּׁנִי חָסֵר וְכוּ':
@39 **אוֹ אָז יִכָּנַע לְבָבָם הֶעָרֵל** כְּמוֹ "אוֹ נוֹדַע כִּי שׁוֹר נַגָּח הוּא" (שמות כא לו). לָשׁוֹן אַחֵר, אוּלַי שֶׁמָּא אָז יִכָּנַע לְבָבָם הֶעָרֵל. **וְאָז יִרְצוּ אֶת עֲוֹנָם** יְכַפְּרוּ עַל עֲוֹנָם בְּיִסּוּרֵיהֶם, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ו:מ"א). וְהַנָּכוֹן בְּעֵינַי שֶׁיֹּאמַר וְהֵבֵאתִי אֹתָם בְּאֶרֶץ אֹיְבֵיהֶם אוֹ עַד זְמַן יִכָּנַע לְבָבָם הֶעָרֵל אוֹ עַד זְמַן יִרְצוּ אֶת עֲוֹנָם בְּאֹרֶךְ הַגָּלוּת. וְהִנֵּה אַחַר "וְהִתְוַדּוּ אֶת עֲוֹנָם" (ויקרא כ"ו:מ') הָיָה רָאוּי שֶׁיֹּאמַר "וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב" (ויקרא כ"ו:מ"ב), כִּי מָה טַעַם "וְהֵבֵאתִי אֹתָם בְּאֶרֶץ אֹיְבֵיהֶם" עַכְשָׁו בַּמָּקוֹם הַזֶּה, וְאֵין עַתָּה הַזְּמַן שֶׁיַּגְלֶה אוֹתָם וִיבִיאֵם בְּאֶרֶץ אוֹיְבֵיהֶם. וּפֵרֵשׁ רַבִּי אַבְרָהָם, אַף אֲנִי כֵּן עָשִׂיתִי עִמָּהֶם וְיִסַּרְתִּים לַהֲבִיאָם בְּאֶרֶץ אוֹיְבֵיהֶם לְהַכְנִיעַ לְבָבָם הֶעָרֵל, וְהִזְכִּיר זֶה בְּכָאן כִּי הִתְוַדּוּ אֶת עֲוֹנָם בַּעֲבוּר שֶׁאֲנִי הַמְּסַבֵּב לָהֶם, כִּי גַּם בִּשְׁעַת קַלְקָלָתָם נִתְכַּוַּנְתִּי בָּהֶם שֶׁיַּעֲשׂוּ תְּשׁוּבָה וְיִתְוַדּוּ. וְעַל דַּעְתִּי יִרְמֹז כִּי אַחַר הַוִּדּוּי יֵלֵךְ עִמָּם בְּקֶרִי, וְיָבִיא אוֹתָם עוֹד בְּאֶרֶץ אוֹיְבֵיהֶם עַד שֶׁיִּכָּנַע לְבָבָם הֶעָרֵל, וְהוּא רֶמֶז שֶׁהֱבִיאָם אֶל הָאָרֶץ וְלֹא נִכְבְּשָׁה לִפְנֵיהֶם, אֲבָל הָיוּ לָהֶם צָרִים וְאוֹיְבִים שָׁם, כְּמוֹ שֶׁנֶּאֱמַר "וַיֹּאמְרוּ צָרֵינוּ" (נחמיה ד ה), "וַיְהִי כַּאֲשֶׁר שָׁמְעוּ אוֹיְבֵינוּ" (שם פסוק ט), וְהָאָרֶץ בְּיַד הָעַמִּים הָיְתָה, כְּמוֹ שֶׁאָמַר עֶזְרָא בִּתְפִלָּתוֹ "הִנֵּה אֲנַחְנוּ הַיּוֹם עֲבָדִים וְהָאָרֶץ אֲשֶׁר נָתַתָּ לַאֲבֹתֵינוּ לֶאֱכֹל אֶת פִּרְיָהּ וְאֶת טוּבָהּ הִנֵּה אֲנַחְנוּ עֲבָדִים עָלֶיהָ וּתְבוּאָתָהּ מַרְבָּה לַמְּלָכִים אֲשֶׁר נָתַתָּ עָלֵינוּ בְּחַטֹּאותֵינוּ וְעַל גְּוִיֹּתֵינוּ מֹשְׁלִים וּבִבְהֶמְתֵּנוּ כִּרְצוֹנָם וּבְצָרָה גְדוֹלָה אֲנָחְנוּ" (שם ט לו לז):
@40 **וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב** אָמַר רַבִּי אַבְרָהָם (אבן עזרא על ויקרא כ"ו:מ"ב) כִּי הוּא מוֹשֵׁךְ עַצְמוֹ וְאַחֵר עִמּוֹ, וְזָכַרְתִּי אֶת בְּרִיתִי בְּרִית יַעֲקוֹב, וְכֵן "הַנְּבוּאָה עוֹדֵד הַנָּבִיא" (דהי"ב טו ח), "רָאשֵׁיכֶם שִׁבְטֵיכֶם" (דברים כט ט). **וְהָאָרֶץ אֶזְכֹּר** טַעְמוֹ אֶזְכֹּר הָאָרֶץ שֶׁפָּרְעָה הַשַּׁבָּתוֹת וְנֶעְזְבָה מֵהֶם, וְאֶזְכֹּר שֶׁהֵם רָצוּ אֶת עֲוֹנָם. וְיִתָּכֵן עַל דֶּרֶךְ הָאֱמֶת שֶׁיֹּאמַר וְזָכַרְתִּי יַעֲקֹב וְיִצְחָק וְאַבְרָהָם שֶׁהֵם בְּנֵי בְּרִית, שֶׁכָּל הַמִּדּוֹת נִקְרְאוּ כֵן בִּהְיוֹתָם בִּבְרִית, וְהָאָרֶץ הַכְּלוּלָה מֵהֶם אֶזְכֹּר בִּכְלָל. וְרַבּוֹתֵינוּ רָמְזוּ כֵן, אָמְרוּ (ויק"ר לו ה), וְלָמָּה הוּא מַזְכִּיר זְכוּת הָאָרֶץ עִמָּהֶם, אָמַר רַבִּי שִׁמְעוֹן בֶּן לָקִישׁ, מָשָׁל לְאָדוֹן שֶׁהָיוּ לוֹ שָׁלֹשׁ בָּנוֹת וְשִׁפְחָה אַחַת מְגַדַּלְתָּן, כָּל זְמַן שֶׁהָאָדוֹן שׁוֹאֵל בִּשְׁלוֹם בְּנוֹתָיו הָיָה אוֹמֵר שַׁאֲלוּ לִי בִּשְׁלוֹם מְגַדַּלְתָּן:
@41 וּפֵרוּשׁ **וְהָאָרֶץ תֵּעָזֵב מֵהֶם** כִּי גַּם אַחֲרֵי הַזְּכִירָה תֵּעָזֵב מֵהֶם, רֶמֶז כִּי אַחֲרֵי פְּקִידַת כּוֹרֶשׁ נֶעֶזְבָה מֵהֶם וְרָצְתָה הַשְּׁמִטּוֹת עַד אַחֲרֵי תְּשַׁע עֶשְׂרֵה שָׁנָה שֶׁנִּבְנָה הַבַּיִת וְקִדְּשׁוּ הָעִיר בִּשְׁתֵּי תּוֹדוֹת (נחמיה יב לא), וְחָזְרָה קְדֻשַּׁת הָאָרֶץ, וְכָרְתוּ אֲמָנָה (שם י א) וְאָמְרוּ (שם י לב), "וְנִטֹּשׁ אֶת הַשָּׁנָה הַשְּׁבִיעִית וּמַשָּׁא כָל יָד". כָּל הַקּוֹרוֹת אוֹתָם רְמוּזוֹת בַּפָּרָשָׁה הַזֹּאת:
@43 וְטַעַם **וְזָכַרְתִּי לָהֶם בְּרִית רִאשֹׁנִים** שֶׁאֶזְכּוֹר לָהֶם כֵּן בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ בַּגָּלוּת הַנִּרְמֶזֶת כָּאן, וְכֵן בְּכָל הַדּוֹרוֹת. וְזֶה טַעַם "לְעֵינֵי הַגּוֹיִם" כִּי יַעֲשֶׂה בָּהֶם בַּעֲבוּר שְׁמוֹ הַגָּדוֹל שֶׁלֹּא יִתְחַלֵּל בַּגּוֹיִם, וְלֹא לְמַעֲנָם, כִּי לֹא עָשׂוּ תְּשׁוּבָה וְלֹא נִתְכַּפְּרוּ עֲוֹנֹתָם. וְכָךְ אָמְרוּ רַבּוֹתֵינוּ (תו"כ פרק ח י), "לֹא מְאַסְתִּים" בִּימֵי אַסְפַּסְיָנוּס, "וְלֹא גְעַלְתִּים" בִּימֵי יָוָן, "לְכַלֹּתָם לְהָפֵר בְּרִיתִי אִתָּם" בִּימֵי הַמָּן, "כִּי אֲנִי ה' אֱלֹהֵיהֶם" בִּימֵי גּוֹג וּמָגוֹג:
@45 **וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר וְגוֹ' אִישׁ כִּי יַפְלִא** גַּם זוֹ הַפָּרָשָׁה דְּבוּקָה, שֶׁהָיְתָה בְּהַר סִינַי מְחֻבֶּרֶת אֶל הַתּוֹכָחוֹת, כִּי הִיא בְּמִשְׁפְּטֵי הַיּוֹבֵל כְּמוֹ שֶׁהִזְכִּיר בְּמַקְדִּישׁ שְׂדֵה מִקְנָה (להלן פסוקים כג-כד) וּשְׂדֵה אֲחֻזָּה (שם יז יח), אֶלָּא שֶׁכָּלַל מִשְׁפְּטֵי כָּל הַנּוֹדְרִים בְּפָרָשָׁה אַחַת. וּלְכָךְ אָמַר בַּסּוֹף, "אֵלֶּה הַמִּצְוֹת אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה אֶל בְּנֵי יִשְׂרָאֵל בְּהַר סִינָי" (ויקרא כ"ז:ל"ד) עַל כָּל הַנֶּאֱמָרוֹת לְמַעְלָה, כִּי מִכָּאן וְאֵילָךְ יְדַבֵּר בְּמִצְוֹת אֹהֶל מוֹעֵד:
@70 **לֹא יַקְדִּישׁ אִישׁ אֹתוֹ** לְשֵׁם קָרְבָּן אַחֵר, לְפִי שֶׁאֵינוֹ שֶׁלּוֹ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ז:כ"ו). וְהַנָּכוֹן שֶׁיֹּאמַר אֵין צֹרֶךְ לְהַקְדִּישׁ אוֹתוֹ, כִּי אִם הוּא שׁוֹר אוֹ שֶׂה לַה' הוּא מֵעַצְמוֹ. וְהִנֵּה הוּא כְּמוֹ שְׁלִילוּת. וּבְמִשְׁנָה תּוֹרָה אָמַר "כָּל הַבְּכוֹר אֲשֶׁר יִוָּלֵד בִּבְקָרְךָ וּבְצֹאנְךָ הַזָּכָר תַּקְדִּישׁ לַה' אֱלֹהֶיךָ" (דברים טו יט), שֶׁיְּהֵא קֹדֶשׁ וְתִנְהֹג בּוֹ קְדֻשָּׁה, שֶׁלֹּא תַּעֲבֹד בּוֹ וְלֹא תָּגֹז אוֹתוֹ וְתֹאכְלֶנּוּ לִפְנֵי הַשֵּׁם, כַּאֲשֶׁר יְפָרֵשׁ:
@71 **וְאִם בַּבְּהֵמָה הַטְּמֵאָה וּפָדָה בְעֶרְכֶּךָ** אֵין מִקְרָא זֶה מוּסָב עַל הַבְּכוֹר, שֶׁאֵין לוֹמַר בִּבְכוֹר בְּהֵמָה טְמֵאָה "וּפָדָה בְּעֶרְכֶּךָ", וַחֲמוֹר אֵין זֶה שֶׁהֲרֵי אֵין פִּדְיוֹן פֶּטֶר חֲמוֹר אֶלָּא טָלֶה, וְהוּא מַתָּנָה לַכֹּהֵן וְאֵינוֹ הֶקְדֵּשׁ. אֶלָּא הַכָּתוּב מוּסָב עַל הַהֶקְדֵּשׁ, שֶׁלְּמַעְלָה דִּבֵּר בְּפִדְיוֹן בְּהֵמָה טְהוֹרָה שֶׁהֻמְּמָה וְכָאן דִּבֵּר בְּמַקְדִּישׁ בְּהֵמָה טְמֵאָה לְבֶדֶק הַבַּיִת, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ז:כ"ז). וְיִתָּכֵן שֶׁנְּתָרֵץ כִּי לְפִי שֶׁאָמַר "אַךְ בְּכוֹר אֲשֶׁר יְבֻכַּר לַה' בִּבְהֵמָה לֹא יַקְדִּישׁ אִישׁ אֹתוֹ" חָזַר וְאָמַר "וְאִם בַּבְּהֵמָה הַטְּמֵאָה" הוּא הַבְּכוֹר שֶׁהִקְדִּישׁ - "וּפָדָה בְּעֶרְכֶּךָ", לְפָרֵשׁ שֶׁאֵין בְּכוֹר נוֹהֵג בִּבְהֵמָה טְמֵאָה אֶלָּא בְּפֶטֶר חֲמוֹר שֶׁכְּבָר נִתְפָּרֵשׁ דִּינוֹ (שמות יג יג). וְלִמֵּד שֶׁאֲפִלּוּ הִקְדִּישׁוֹ אֵינוֹ קָדוֹשׁ כְּדִין בְּכוֹר, אֶלָּא כִּשְׁאָר הֶקְדֵּשׁ הוּא וְנִפְדֶּה. וּלְכָךְ אָמַר שֶׁיִּפְדֶּה אוֹתוֹ הַמַּקְדִּישׁ בְּתוֹסֶפֶת חֹמֶשׁ, וְאַחַר יִקְנֶה אוֹתוֹ בְּעֶרְכְּךָ. וְהַכָּתוּב שֶׁל מַעְלָה "וְאִם כָּל בְּהֵמָה טְמֵאָה אֲשֶׁר לֹא יַקְרִיבוּ מִמֶּנָּה" (ויקרא כ"ז:י"א), עַל פִּי פְּשׁוּטוֹ בִּבְהֵמָה טְמֵאָה. וְעַל מִדְרַשׁ רַבּוֹתֵינוּ (תמורה לב) הַכָּתוּב מְיֻתָּר, בַּעֲבוּר שֶׁכָּפַל "טְמֵאָה אֲשֶׁר לֹא יַקְרִיבוּ מִמֶּנָּה קָרְבָּן לַה'", לְפִיכָךְ יִדְרְשׁוּ, וְאִם כָּל בְּהֵמָה טְמֵאָה וַאֲשֶׁר לֹא יַקְרִיבוּ מִמֶּנָּה קָרְבָּן לַה', לְרַבּוֹת בַּעֲלֵי מוּמִין קְבוּעִין שֶׁאֵין מַקְרִיבִים מֵהֶן קָרְבָּן לַה':
@73 **כָּל חֵרֶם אֲשֶׁר יָחֳרַם מִן הָאָדָם** הַיּוֹצֵא לֵהָרֵג וְאָמַר אֶחָד "עֶרְכּוֹ עָלַי" לֹא אָמַר כְּלוּם. **מוֹת יוּמָת** הֲרֵי הוּא הוֹלֵךְ לָמוּת, לְפִיכָךְ לֹא יִפָּדֶה, אֵין לוֹ דָּמִים וְלֹא עֵרֶךְ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ז:כ"ט). וְרַבּוֹתֵינוּ נֶחְלְקוּ בַּדָּבָר (ערכין ו), וְיֵשׁ מֵהֶם אוֹמְרִים שֶׁהוּא אַזְהָרָה לְחַיָּבֵי מִיתוֹת שֶׁאֵין לוֹקְחִין מֵהֶן כֹּפֶר לְפָטְרָן. וְיִתָּכֵן שֶׁהִזְכִּיר זֶה בְּכָאן לוֹמַר שֶׁלֹּא יִתֵּן מָמוֹן לַשֵּׁם כִּשְׁאָר הַחֲרָמִים וְיִפָּטֵר. וְעַל דֶּרֶךְ הַפְּשָׁט יֹאמַר הַכָּתוּב כִּי כָּל הַמַּחְרִים מִשֶּׁלּוֹ בֵּין אָדָם בֵּין בְּהֵמָה וּשְׂדֵה אֲחֻזָּתוֹ, הוּא קֹדֶשׁ לַשֵּׁם, שֶׁהֵן חֲרָמִים לַכֹּהֲנִים וְאֵין לָהֶם פִּדְיוֹן, אֲבָל הַמַּחְרִים מִן הָאָדָם שֶׁאֵינוֹ שֶׁלּוֹ, כְּגוֹן הַנִּלְחָמִים עַל אוֹיְבֵיהֶם וְנוֹדְרִים נֶדֶר "אִם נָתֹן תִּתֵּן אֶת הָעָם הַזֶּה בְּיָדִי וְהַחֲרַמְתִּי אֶת עָרֵיהֶם" (במדבר כא ב) - יָמוּתוּ כָּל הָאָדָם הַנִּמְצָא בָּהֶם. וְהַטַּעַם שֶׁאֵין דַּעַת הַנּוֹדֵר כֵּן לְתִתּוֹ לַכֹּהֲנִים, רַק שֶׁיִּהְיֶה הַכֹּל אָסוּר בַּהֲנָאָה, כִּי נִתְכַּוֵּן לְהַכְרִית הָאוֹיְבִים וּלְכַלּוֹתָם. וּמָצִינוּ אַנְשֵׁי יָבֵשׁ גִּלְעָד שֶׁעָבְרוּ עַל שְׁבוּעַת הַקָּהָל וְלֹא בָּאוּ אֶל הַמִּצְפָּה, וּכְתִיב "וַיִּשְׁלְחוּ שָׁם הָעֵדָה שְׁנֵים עָשָׂר אֶלֶף אִישׁ מִבְּנֵי הֶחָיִל וַיְצַוּוּ אוֹתָם לֵאמֹר לְכוּ וְהִכִּיתֶם אֶת יוֹשְׁבֵי יָבֵשׁ גִּלְעָד לְפִי חֶרֶב". וְאֵין הַסְּבָרָא נוֹתֶנֶת שֶׁעָשׂוּ כָּל הָעֵדָה רָעָה כָּזֹאת לְהָמִית אֲנָשִׁים רַבִּים מִיִּשְׂרָאֵל שֶׁאֵינָם חַיָּבִים מִיתָה, וּפִנְחָס הָיָה שָׁם וְעַל פִּיו נַעֲשָׂה כָּל הָעִנְיָן הַהוּא. וְעוֹד מָצָאתִי בְּאַגָּדָה בִּילַמְּדֵנוּ, תַּנְיָא רַבִּי עֲקִיבָא אוֹמֵר, הַחֵרֶם הוּא הַשְּׁבוּעָה וְהַשְּׁבוּעָה הוּא הַחֵרֶם; אַנְשֵׁי יָבֵשׁ עָבְרוּ עַל הַחֵרֶם וְנִתְחַיְּבוּ מִיתָה. וּלְכָךְ אֲנִי אוֹמֵר כִּי מִן הַכָּתוּב הַזֶּה יָצָא לָהֶם הַדִּין הַזֶּה, שֶׁכָּל מֶלֶךְ בְּיִשְׂרָאֵל אוֹ סַנְהֶדְרֵי גְּדוֹלָה בְּמַעֲמַד כָּל יִשְׂרָאֵל שֶׁיֵּשׁ לָהֶם רְשׁוּת בַּמִּשְׁפָּטִים, אִם יַחְרִימוּ עַל עִיר לְהִלָּחֵם עָלֶיהָ וְכֵן אִם יַחְרִימוּ עַל דָּבָר - הָעוֹבֵר עָלָיו חַיָּב מִיתָה, וְהוּא חִיּוּבָן שֶׁל אַנְשֵׁי יָבֵשׁ גִּלְעָד וְשֶׁל יְהוֹנָתָן שֶׁאָמַר לוֹ אָבִיו "כֹּה יַעֲשֶׂה אֱלֹהִים וְכֹה יוֹסִף כִּי מוֹת תָּמוּת יוֹנָתָן" (שמואל א יד מד), וּמֵהֵיכָן נִתְחַיְּבוּ אֵלּוּ מִיתָה מִן הַדִּין חוּץ מִן הַמָּקוֹם הַזֶּה. וְזֶה הָיָה טָעוּתוֹ שֶׁל יִפְתָּח בְּבִתּוֹ, כִּי חָשַׁב כַּאֲשֶׁר חֵרֶם נְגִיד יִשְׂרָאֵל חָל וְקַיָּם לְהָמִית אֲנָשִׁים אוֹ הָעוֹבֵר עַל חֶרְמוֹ חַיָּב מִיתָה, כֵּן אִם נָדַר בְּעֵת מִלְחָמָה לַעֲשׂוֹת מֵאִישׁ אוֹ אֲנָשִׁים זֶבַח יָחוּל הַנֶּדֶר, וְלֹא יָדַע כִּי חֵרֶם הַמֶּלֶךְ וְהַסַּנְהֶדְרִין חָל עַל הַמּוֹרְדִים לְכַלּוֹתָם אוֹ עַל הָעוֹבֵר גְּזֵרָתָם וְתַקָּנָתָם, אֲבָל לָחוּל הַנֶּדֶר לַעֲשׂוֹת עוֹלָה מִדָּבָר שֶׁאֵין רָאוּי לַה' - חָס וְחָלִילָה. וּלְכָךְ אָמַר בִּב"ר (ס ג), שֶׁאֲפִלּוּ הֶקְדֵּשׁ דָּמִים לֹא הָיָה חַיָּב, וְנֶעֱנַשׁ בְּדָמָהּ. וְאַל תִּהְיֶה נִפְתֶּה בְּהֶבְלֵי ר"א הָאוֹמֵר כִּי פֵּרוּשׁ "וְהַעֲלִיתִהוּ עוֹלָה" (שופטים יא לא) אוֹ וְהֶעֱלִיתִיהוּ, לוֹמַר אִם יִהְיֶה הַיּוֹצֵא מִדַּלְתֵי בֵּיתִי אִישׁ אוֹ אִשָּׁה - וְהָיָה לַה' קֹדֶשׁ, שֶׁיִּהְיֶה פָּרוּשׁ מִדַּרְכֵי הָעוֹלָם לַעֲמֹד לְשָׁרֵת בְּשֵׁם ה' בִּתְפִלָּה וְהֹדוֹת לֵאלֹהִים; וְאִם יִהְיֶה דָּבָר רָאוּי לִקָּרֵב אַעֲלֶנּוּ עוֹלָה; וְעָשָׂה בַּיִת לְבִתּוֹ מִחוּץ לָעִיר וְהִתְבּוֹדְדָה שָׁם וְכִלְכְּלָהּ כָּל יָמֶיהָ וְאִישׁ לֹא יְדָעָהּ, וְהָיְתָה בִּתּוֹ צְרוּרָה שָׁם. וְאֵלֶּה דִּבְרֵי רוּחַ, כִּי אִם נָדַר שֶׁיִּהְיֶה לַה' אֵינֶנּוּ שֶׁיִּהְיֶה פָּרוּשׁ, אֲבָל יִהְיֶה כְּמוֹ שְׁמוּאֵל שֶׁאָמְרָה אִמּוֹ "וּנְתַתִּיו לַה'" (שמואל א א יא), וְהָיָה מְשָׁרֵת בְּבֵית ה', לֹא פָּרוּשׁ. וּכְפִי מִשְׁפְּטֵי הַתּוֹרָה אֵין בְּיַד הָאָדָם שֶׁיִּדֹּר בְּיוֹצְאֵי פֶּתַח בֵּיתוֹ שֶׁיִּהְיוּ פְּרוּשִׁים כַּאֲשֶׁר אֵין בְּיָדוֹ לְהַעֲלוֹתָם עוֹלָה. וְאִם הַדָּבָר כֵּן, הָיְתָה בִּתּוֹ הַבּוֹכָה עַל בְּתוּלֶיהָ וְרַעְיוֹתֶיהָ עִמָּהּ כְּזוֹנוֹת לְקַלֵּס אֶתְנָן, וְח"ו שֶׁיִּהְיֶה חֹק בְּיִשְׂרָאֵל לְתַנּוֹת לְבַת יִפְתָּח אַרְבַּעַת יָמִים בַּשָּׁנָה מִפְּנֵי שֶׁלֹּא נִשֵּׂאת לְבַעַל וְהָיְתָה עוֹבֶדֶת אֶת ה' בְּטַהֲרָה. אֲבָל הַדָּבָר כִּפְשׁוּטוֹ, וְטָעוּתוֹ הָיָה מִמַּה שֶׁאָמַרְתִּי. וּלְדַעַת רַבּוֹתֵינוּ זַ"ל יִתָּכֵן שֶׁיִּהְיֶה הַכָּתוּב הַזֶּה כּוֹלֵל דְּבָרִים רַבִּים, כְּמוֹ "לֹא תֹאכְלוּ עַל הַדָּם" (ויקרא י"ט:כ"ו), וּכְמוֹ "לֹא יוּמְתוּ אָבוֹת עַל בָּנִים" (דברים כד טז), שֶׁהֵם דּוֹרְשִׁים אוֹתוֹ בִּפְסוּל עֵדוּת הַקְּרוֹבִים (סנהדרין כז), וְהַכָּתוּב אוֹמֵר בּוֹ עוֹד "וְאֶת בְּנֵי הַמַּכִּים לֹא הֵמִית כַּכָּתוּב בְּסֵפֶר תּוֹרַת מֹשֶׁה אֲשֶׁר צִוָּה ה' לֵאמֹר לֹא יוּמְתוּ אָבוֹת עַל בָּנִים וּבָנִים לֹא יוּמְתוּ עַל אָבוֹת" (מלכים ב יד ו). וְכֵן זֶה הַכָּתוּב יִכְלֹל דִּין הַמַּעֲרִיךְ מְחֻיְּבֵי מִיתָה, וְדִין מִי שֶׁמַּחְרִימִים אוֹתוֹ בְּעֵת הַכִּבּוּשׁ כְּמוֹ שֶׁאָמַרְנוּ, וְהָעוֹבֵר עַל הַחֵרֶם שֶׁל בֵּית דִּין הַגָּדוֹל אוֹ שֶׁל מֶלֶךְ יִשְׂרָאֵל כְּעִנְיַן מַעֲשֵׂה שָׁאוּל. וְזֶהוּ שֶׁנֶּאֱמַר שָׁם "וַיִּפְדּוּ הָעָם אֶת יְהוֹנָתָן וְלֹא מֵת" (שמואל א יד מה), כִּי כְּלַפֵּי מַה שֶׁאָמְרָה בּוֹ תּוֹרָה "לֹא יִפָּדֶה מוֹת יוּמָת" אָמַר שָׁם "וַיִּפְדּוּ הָעָם אֶת יוֹנָתָן וְלֹא מֵת", כִּי בַּעֲבוּר שֶׁאֵרַע נֵס עַל יָדוֹ יָדְעוּ כִּי בְּשׁוֹגֵג עָשָׂה. וְזֶה טַעַם "אֲשֶׁר עָשָׂה הַיְשׁוּעָה הַגְּדוֹלָה הַזֹּאת בְּיִשְׂרָאֵל" (שם). וְכֵן תִּרְגֵּם יוֹנָתָן בֶּן עֻזִּיאֵל "אֲרֵי קֳדָם ה' גְּלֵי דִּבְשָׁלוּ עֲבַד יוֹמָא דֵּין וּפְרַק עַמָּא יָת יוֹנָתָן":
@73 וְנִשְׁלַם סֵפֶר תּוֹרַת הַכֹּהֲנִים וְקָרְבְּנוֹתָן וּמִצְוָתָן, יְשׁוֹבֵב אֵל עֶלְיוֹן דְּבָרִים לַהֲוָיָתָן, לְוִיִּם לְשִׁירָן וּלְזִמְרָן וְכֹהֲנִים לַעֲבוֹדָתָן, וְיִשְׂרָאֵל אֶל נְוֵה אֵיתָן, עֵינֵינוּ תִּרְאֶינָה יְרוּשָׁלַיִם גִּנַּת בִּיתָן, וְאַרְמוֹן עַל מִשְׁפָּטוֹ הֵיכָל וּדְבִיר עַל מְכוֹנָתָן, וּבְנוֹת יְהוּדָה בְּשַׁלְוָתָן, וְעָרְבָה לַה' מִנְחַת יְהוּדָה כִּימֵי עוֹלָם וּכְשָׁנִים כְּקַדְמוּתָן, יַעֲלוּ עַל רָצוֹן מִזְבְּחוֹ תְּמִידִין כְּסִדְרָן וּמוּסָפִין כְּהִלְכָתָן:
@73 תם ונשלם ספר ויקרא בעז"ה:
